const puppeteer = require('puppeteer-core');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = process.argv[2];
const OUT = process.argv[3];
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

const server = http.createServer((req, res) => {
  let p = decodeURIComponent(req.url.split('?')[0]);
  const f = path.join(ROOT, p);
  if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); return res.end(); }
  const type = f.endsWith('.html') ? 'text/html' : f.endsWith('css2') ? 'text/css' : 'application/octet-stream';
  res.writeHead(200, { 'Content-Type': type });
  fs.createReadStream(f).pipe(res);
}).listen(8765);

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME, headless: 'new',
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--no-sandbox'],
  });
  const sites = { A: 'saved_resource.html', B: 'saved_resource(1).html' };
  for (const [k, file] of Object.entries(sites)) {
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    const logs = [];
    page.on('console', m => logs.push(`[${m.type()}] ${m.text()}`));
    page.on('pageerror', e => logs.push(`[pageerror] ${e.message}`));
    page.on('requestfailed', r => logs.push(`[reqfail] ${r.url().slice(0, 120)}`));
    await page.goto(`http://localhost:8765/${encodeURIComponent(file)}`, { waitUntil: 'networkidle2', timeout: 60000 }).catch(e => logs.push('goto ' + e.message));
    await new Promise(r => setTimeout(r, 4000));
    await page.screenshot({ path: path.join(OUT, `${k}_viewport.png`) });
    await page.screenshot({ path: path.join(OUT, `${k}_full.png`), fullPage: true });
    const info = await page.evaluate(() => {
      const vis = el => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; };
      const ctrls = [...document.querySelectorAll('button, a, input, select, textarea, [role=button], [role=slider], [role=tab]')]
        .filter(vis).map(e => `${e.tagName}${e.type ? '[' + e.type + ']' : ''} "${(e.innerText || e.value || e.getAttribute('aria-label') || '').trim().replace(/\s+/g, ' ').slice(0, 60)}" ${e.getAttribute('href') || ''}`);
      const canvases = [...document.querySelectorAll('canvas')].map(c => `${c.width}x${c.height} @(${Math.round(c.getBoundingClientRect().top)})`);
      return { title: document.title, h: document.documentElement.scrollHeight, text: document.body.innerText.slice(0, 6000), ctrls, canvases };
    });
    fs.writeFileSync(path.join(OUT, `${k}_info.txt`), JSON.stringify(info, null, 2) + '\n\nLOGS:\n' + logs.join('\n'));
    console.log(k, info.title, 'height', info.h, 'canvases', info.canvases, 'controls', info.ctrls.length, 'logs', logs.length);
    await page.close();
  }
  await browser.close();
  server.close();
})();

