const puppeteer = require('puppeteer-core');
const http = require('http');
const fs = require('fs');
const path = require('path');
const ROOT = process.argv[2], OUT = process.argv[3];
const server = http.createServer((req, res) => {
  const f = path.join(ROOT, decodeURIComponent(req.url.split('?')[0]));
  if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'Content-Type': f.endsWith('.html') ? 'text/html' : f.endsWith('css2') ? 'text/css' : 'application/octet-stream' });
  fs.createReadStream(f).pipe(res);
}).listen(8770);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const FILES = { A: 'saved_resource.html', B: 'saved_resource(1).html' };

(async () => {
  const browser = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: 'new', args: ['--no-sandbox'] });
  for (const k of ['A', 'B']) {
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    const log = [];
    page.on('console', m => { if (m.type() === 'error') log.push(`[console.error] ${m.text()}`); });
    page.on('pageerror', e => log.push(`[pageerror] ${e.message}`));
    await page.goto(`http://localhost:8770/${encodeURIComponent(FILES[k])}`, { waitUntil: 'networkidle2' });
    await sleep(2000);
    const baseText = await page.evaluate(() => document.body.innerText);
    const diff = async () => {
      const t = await page.evaluate(() => document.body.innerText);
      return t.split('\n').filter(l => l.trim() && !baseText.includes(l)).join(' | ').slice(0, 500);
    };
    // largest svg = main chart
    const svgBox = await page.evaluate(() => {
      const s = [...document.querySelectorAll('svg')].map(e => ({ e, r: e.getBoundingClientRect() })).sort((a, b) => b.r.width * b.r.height - a.r.width * a.r.height)[0];
      return { x: s.r.x, y: s.r.y, w: s.r.width, h: s.r.height };
    });
    log.push('main svg ' + JSON.stringify(svgBox));
    // hover sweep along chart
    for (const fx of [0.05, 0.3, 0.55, 0.8, 0.97]) {
      const x = svgBox.x + svgBox.w * fx, y = svgBox.y + svgBox.h * 0.75;
      await page.mouse.move(x, y, { steps: 4 }); await sleep(500);
      log.push(`hover chart @${fx}: ${await diff()}`);
      if (fx === 0.3) await page.screenshot({ path: path.join(OUT, `${k}_hover_chart.png`) });
    }
    await page.mouse.move(5, 5); await sleep(400);
    // event markers
    const sel = k === 'A' ? 'button[aria-label*=", 20"]' : 'g[aria-label*="Press Enter"]';
    const markers = await page.$$(sel);
    log.push(`markers found: ${markers.length}`);
    let i = 0;
    for (const m of markers) {
      const box = await m.boundingBox(); if (!box) continue;
      await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2, { steps: 3 }); await sleep(600);
      const label = await m.evaluate(e => e.getAttribute('aria-label'));
      const d = await diff();
      log.push(`hover marker ${i} [${label.slice(0, 50)}] @(${Math.round(box.x)},${Math.round(box.y)}) ${Math.round(box.width)}x${Math.round(box.height)} → ${d.slice(0, 300)}`);
      if (i === 0 || i === 6 || i === markers.length - 1) await page.screenshot({ path: path.join(OUT, `${k}_hover_marker_${i}.png`) });
      await page.mouse.move(5, 5); await sleep(300);
      i++;
    }
    // click one marker
    if (markers[3]) {
      const box = await markers[3].boundingBox();
      await page.mouse.click(box.x + box.width / 2, box.y + box.height / 2); await sleep(900);
      log.push(`CLICK marker 3 → ${await diff()}`);
      await page.screenshot({ path: path.join(OUT, `${k}_click_marker.png`) });
      await page.keyboard.press('Escape'); await sleep(500);
      await page.mouse.click(5, 5); await sleep(400);
    }
    fs.writeFileSync(path.join(OUT, `${k}_hover.txt`), log.join('\n'));
    console.log(k, 'markers', markers.length);
    await page.close();
  }
  await browser.close(); server.close();
})();

