// Overlap scanner: flags visible text boxes that intersect other text or graphics (svg/img/canvas) they don't belong to,
// plus text clipped by overflow and elements sticking out of the viewport horizontally.
// usage: node overlap.js <filesDir> <htmlFile> <outDir> <tag> [width] [height]
const puppeteer = require('puppeteer-core'); const http = require('http'); const fs = require('fs'); const path = require('path');
const [ROOT, FILE, OUT, TAG, W = '1440', H = '900'] = process.argv.slice(2);
const types = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript', '.png': 'image/png', '.jpg': 'image/jpeg', '.svg': 'image/svg+xml' };
const server = http.createServer((req, res) => {
  const f = path.join(ROOT, decodeURIComponent(req.url.split('?')[0]));
  if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'Content-Type': types[path.extname(f)] || (/css2/.test(f) ? 'text/css' : 'text/html') }); fs.createReadStream(f).pipe(res);
}).listen(0);
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const b = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: 'new', args: ['--no-sandbox', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const p = await b.newPage(); await p.setViewport({ width: +W, height: +H });
  await p.goto(`http://localhost:${server.address().port}/${encodeURIComponent(FILE)}`, { waitUntil: 'networkidle2', timeout: 60000 });
  // scroll through to trigger lazy/reveal animations
  const total = await p.evaluate(() => document.documentElement.scrollHeight);
  for (let y = 0; y < total; y += +H / 2) { await p.evaluate(y => scrollTo(0, y), y); await sleep(250); }
  await p.evaluate(() => scrollTo(0, 0)); await sleep(1500);
  const found = await p.evaluate(() => {
    const vis = e => { const s = getComputedStyle(e); if (s.visibility === 'hidden' || s.display === 'none' || +s.opacity === 0) return false; const r = e.getBoundingClientRect(); return r.width > 2 && r.height > 2; };
    const abs = r => ({ x: r.left + scrollX, y: r.top + scrollY, w: r.width, h: r.height });
    // text runs: use Range rects on text nodes
    const texts = [];
    const tw = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    while (tw.nextNode()) {
      const n = tw.currentNode; const t = n.textContent.trim(); if (t.length < 2) continue;
      const el = n.parentElement; if (!el || !vis(el) || el.closest('script,style,noscript,[aria-hidden=true] title')) continue;
      const rg = document.createRange(); rg.selectNodeContents(n); const r = rg.getBoundingClientRect(); if (r.width < 2) continue;
      // skip ancestors hidden by opacity
      let o = el, hidden = false; while (o) { if (+getComputedStyle(o).opacity === 0) { hidden = true; break; } o = o.parentElement; } if (hidden) continue;
      texts.push({ el, t: t.slice(0, 40), r: abs(r) });
    }
    const graphics = [...document.querySelectorAll('svg, img, canvas, video')].filter(e => vis(e) && !(e.parentElement && e.parentElement.closest('svg'))).map(e => ({ el: e, r: abs(e.getBoundingClientRect()), d: (e.getAttribute('aria-label') || e.getAttribute('alt') || e.tagName).slice(0, 30) }));
    const inter = (a, b) => { const x = Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)); const y = Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y)); return x * y; };
    const out = [];
    for (let i = 0; i < texts.length; i++) for (let j = i + 1; j < texts.length; j++) {
      const A = texts[i], B = texts[j]; if (A.el === B.el || A.el.contains(B.el) || B.el.contains(A.el)) continue;
      const ov = inter(A.r, B.r); if (ov > 0.15 * Math.min(A.r.w * A.r.h, B.r.w * B.r.h)) out.push(`TEXT×TEXT "${A.t}" vs "${B.t}" @y=${Math.round(A.r.y)} ov=${Math.round(ov)}`);
    }
    for (const T of texts) for (const G of graphics) {
      if (G.el.contains(T.el) || T.el.contains(G.el)) continue;
      // ignore icons (small graphics) and full-bleed backgrounds (very large)
      if (G.r.w < 40 || G.r.h < 40 || G.r.w * G.r.h > 0.5 * innerWidth * innerHeight) continue;
      // ignore graphics that sit behind text as decoration in same card? keep: real overlaps are what we want to see
      const ov = inter(T.r, G.r); if (ov > 0.2 * T.r.w * T.r.h) out.push(`TEXT×GFX "${T.t}" over <${G.d}> @y=${Math.round(T.r.y)} textBox=${Math.round(T.r.w)}x${Math.round(T.r.h)} gfx=${Math.round(G.r.w)}x${Math.round(G.r.h)}@(${Math.round(G.r.x)},${Math.round(G.r.y)})`);
    }
    // clipped text (scrollWidth > clientWidth with overflow hidden)
    for (const e of document.querySelectorAll('body *')) {
      if (!vis(e) || !e.childNodes.length) continue; const s = getComputedStyle(e);
      if ((s.overflow.includes('hidden') || s.textOverflow === 'ellipsis') && e.scrollWidth > e.clientWidth + 2 && e.innerText && e.innerText.trim().length > 1 && e.children.length === 0) out.push(`CLIPPED "${e.innerText.trim().slice(0, 40)}" ${e.scrollWidth}>${e.clientWidth}`);
    }
    const docW = document.documentElement.scrollWidth; if (docW > innerWidth + 1) out.push(`H-OVERFLOW page scrollWidth ${docW} > ${innerWidth}`);
    return out;
  });
  const uniq = [...new Set(found)];
  fs.writeFileSync(path.join(OUT, `overlap_${TAG}_${W}.txt`), uniq.join('\n'));
  console.log(`${TAG} ${W}x${H}: ${uniq.length} findings`); console.log(uniq.slice(0, 40).join('\n'));
  await b.close(); server.close();
})();

