  const cv = await f.$('canvas'); let bb = await cv.boundingBox();
  const grab = async () => { bb = await cv.boundingBox(); return crypto.createHash('md5').update(await page.screenshot({ clip: { x: Math.max(0, bb.x), y: Math.max(0, bb.y), width: Math.min(bb.width, 1000 - bb.x), height: Math.min(bb.height, 800 - Math.max(0, bb.y)) } })).digest('hex'); };
  const moving = async () => { const a = await grab(); await sleep(1500); return a !== await grab(); };
  const dlg = () => f.evaluate(() => [...document.querySelectorAll('[role=dialog],[aria-modal=true],dialog[open]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.trim().replace(/\s+/g, ' ').slice(0, 120)));
  const toast = () => f.evaluate(() => [...document.querySelectorAll('[role=status],[role=alert],[aria-live]')].map(d => d.innerText.trim()).filter(Boolean).join(' | ').slice(0, 120));

  log.push(`idle: canvas moving=${await moving()}`);
  // accents
  for (const a of ['Cobalt accent', 'Graphite accent', 'Coral accent']) { await s.click({ label: a }, 1200); await shot('accent_' + a.split(' ')[0]); }
  // auto-rotate
  await s.click({ label: 'Auto-rotate' }, 500); log.push(`auto-rotate on: moving=${await moving()} pressed=${await f.evaluate(() => [...document.querySelectorAll('button')].find(b => /auto-rotate/i.test(b.getAttribute('aria-label') || b.innerText))?.getAttribute('aria-pressed'))}`);
  await s.click({ label: 'Auto-rotate' }, 1200); log.push(`auto-rotate off: moving=${await moving()}`);
  // grid, wireframe
  await s.click({ label: 'Toggle floor grid' }, 900); await shot('grid');
  await s.click({ label: 'Toggle wireframe view' }, 900); await shot('wire'); await s.click({ label: 'Toggle wireframe view' }, 600); await s.click({ label: 'Toggle floor grid' }, 600);
  // camera select via keyboard on the real select
  const sel = await f.$('select');
  if (sel) {
    const opts = await sel.evaluate(e => [...e.options].map(o => o.value + ':' + o.text)); log.push('camera options ' + JSON.stringify(opts));
    for (const o of opts) { const v = o.split(':')[0]; await sel.select(v); await sleep(1500); await shot('cam_' + v); }
    await sel.select(opts[0].split(':')[0]); await sleep(800);
  }
  // drag then reset
  bb = await cv.boundingBox(); await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 2); await page.mouse.down(); await page.mouse.move(bb.x + bb.width / 2 + 160, bb.y + bb.height / 2 + 20, { steps: 10 }); await page.mouse.up(); await sleep(800); await shot('dragged');
  await s.click({ label: 'Reset camera view' }, 1500); await shot('reset');
  // customize: banner designs
  await s.click({ label: 'Customize model' }, 900);
  for (const d of ['Ocean', 'Monochrome', 'Spectrum']) { await s.click({ text: d }, 1200); }
  log.push('customize dialog: ' + JSON.stringify(await dlg()));
  await s.click({ text: 'Ocean' }, 1000); await page.keyboard.press('Escape'); await sleep(800);
  log.push('after Esc dialogs: ' + JSON.stringify(await dlg())); await shot('banner_ocean');
  await s.click({ label: 'Customize model' }, 900); await s.click({ text: 'Spectrum' }, 800); await s.click({ text: 'Looking good' }, 800);
  log.push('after Looking good: ' + JSON.stringify(await dlg()));
  // expand viewer + close
  await s.click({ label: 'Expand 3D viewer' }, 1000); await shot('expanded');
  await page.keyboard.press('Escape'); await sleep(800);
  log.push('expanded after Esc: ' + await f.evaluate(() => document.body.innerText.includes('Big format.') && !!document.querySelector('canvas') ? `canvas w=${document.querySelector('canvas').getBoundingClientRect().width}` : '?'));
  await shot('after_expand_esc');
  const exitBtn = await s.find({ label: 'Exit full view' }) || await s.find({ label: 'Collapse 3D viewer' }) || await s.find({ label: 'Close' });
  log.push('collapse button: ' + (exitBtn ? await exitBtn.evaluate(e => e.getAttribute('aria-label')) : 'none'));
