// Start a T20 batting match and watch the delivery cycle (no input), dumping candidate moving elements.
const { open, sleep } = require('./frame'); const path = require('path'); const fs = require('fs');
const [ROOT, FILE, OUT, TAG] = process.argv.slice(2);
(async () => {
  const s = await open(ROOT, FILE, { width: 1440, height: 900, sandbox: false }); await sleep(2000);
  const { frame: f, page, log } = s;
  await s.click({ text: 'LET’S PLAY' }, 1500);
  // candidate elements: ball, marker, needle, etc
  const cands = await f.evaluate(() => [...document.querySelectorAll('*')].filter(e => /ball|marker|needle|indicator|cursor|pointer|sweet|zone|meter|timing|bat|bowler|batter|striker/i.test((e.className && e.className.baseVal !== undefined ? e.className.baseVal : e.className) + ' ' + (e.id || ''))).slice(0, 60).map(e => `${e.tagName.toLowerCase()}.${(e.className.baseVal !== undefined ? e.className.baseVal : e.className).toString().slice(0, 60)}${e.id ? '#' + e.id : ''}`));
  log.push('CANDIDATES:\n  ' + [...new Set(cands)].join('\n  '));
  const t0 = Date.now();
  for (let i = 0; i < 40; i++) {
    const st = await f.evaluate(() => {
      const q = sel => document.querySelector(sel);
      const txt = document.body.innerText;
      const score = (txt.match(/\n(\d+)\s*\/\s*(\d+)\b/) || [''])[0].replace(/\s+/g, '');
      const overs = (txt.match(/(\d+\.\d)\s*\/\s*(20|50)/) || [''])[0];
      // any element whose class contains 'ball' : report its position
      const balls = [...document.querySelectorAll('[class*=ball i]')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.width < 40; }).map(e => { const r = e.getBoundingClientRect(); return `${Math.round(r.x)},${Math.round(r.y)}`; }).slice(0, 2);
      const markers = [...document.querySelectorAll('[class*=marker i],[class*=needle i],[class*=cursor i],[class*=indicator i]')].filter(e => e.getBoundingClientRect().width > 0).map(e => { const r = e.getBoundingClientRect(); return `${e.className.toString().slice(0, 25)}@${Math.round(r.x)}`; }).slice(0, 3);
      const msgs = [...document.querySelectorAll('[aria-live],[role=status]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 120);
      return { score, overs, balls, markers, msgs };
    });
    log.push(`${((Date.now() - t0) / 1000).toFixed(1)}s ${JSON.stringify(st)}`);
    if (i % 8 === 0) await s.shot(path.join(OUT, `${TAG}_explore_${i}.png`));
    await sleep(250);
  }
  fs.writeFileSync(path.join(OUT, `${TAG}_explore.txt`), log.join('\n'));
  console.log(log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

