// Auto-player: bats with good timing for N balls, then mistimes to lose wickets, logs every ball.
// usage: node cricket_play.js <filesDir> <file> <outDir> <A|B> <mode: bat|bowl> <goodBalls> <badBalls> [format T20|ODI] [width]
const { open, sleep } = require('./frame'); const path = require('path'); const fs = require('fs');
const [ROOT, FILE, OUT, TAG, MODE = 'bat', GOOD = '12', BAD = '20', FORMAT = 'T20', WIDTH = '1440'] = process.argv.slice(2);
const CFG = {
  A: { cursor: '.meter-cursor', zone: '.meter-sweet-zone', keys: ['s', 'd', 'a', 's'], bowlKey: ' ' },
  B: { cursor: '.meter-needle', zone: '.meter-zone', keys: [' '], bowlKey: ' ' },
}[TAG];
(async () => {
  const W = +WIDTH, H = W >= 1440 ? 900 : 800;
  const s = await open(ROOT, FILE, { width: W, height: H, sandbox: W < 1440 }); await sleep(2000);
  const { frame: f, page, log } = s;
  const shotN = { n: 0 }; const shot = n => s.shot(path.join(OUT, `${TAG}_${MODE}_${FORMAT}_${String(++shotN.n).padStart(2, '0')}_${n}.png`));
  if (FORMAT === 'ODI') await s.click({ text: 'ODI' }, 600);
  if (MODE === 'bowl') await s.click({ text: 'Bowling' }, 600);
  await s.click({ text: 'LET’S PLAY' }, 800);
  // focus the game area so key events land in the frame
  const state = () => f.evaluate((c) => {
    const cur = document.querySelector(c.cursor), zone = document.querySelector(c.zone);
    const cr = cur && cur.getBoundingClientRect(), zr = zone && zone.getBoundingClientRect();
    const txt = document.body.innerText;
    const sc = txt.match(/(\d+)\s*\/\s*(\d+)\s*\n?[^\n]{0,30}?\n?\s*(\d+\.\d)\s*\/\s*(\d+)/) || txt.match(/(\d+)\s*\/\s*(\d+)/);
    const ov = (txt.match(/(\d+\.\d)\s*\/\s*(20|50)/) || [])[1];
    const live = [...document.querySelectorAll('[aria-live],[role=status]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 140);
    return { cx: cr ? cr.x + cr.width / 2 : null, zl: zr ? zr.x : null, zr: zr ? zr.x + zr.width : null, score: sc ? `${sc[1]}/${sc[2]}` : '?', ov, live };
  }, CFG);
  const start = Date.now(); let ball = 0; let lastOv = (await state()).ov; let prevCx = null; let hitThis = false; let mode = 'good';
  const total = +GOOD + +BAD; const rows = []; let lastScore = (await state()).score;
  let idleSince = Date.now();
  while (ball < total && Date.now() - start < 12 * 60 * 1000) {
    const st = await state();
    if (st.ov !== lastOv) { // ball completed
      ball++;
      await sleep(250);
      const st2 = await state();
      rows.push(`ball ${ball} [${mode}] ov ${lastOv}->${st.ov} score ${lastScore}->${st2.score} | ${st2.live}`);
      lastScore = st2.score; lastOv = st.ov; hitThis = false; idleSince = Date.now();
      if (ball === +GOOD) { mode = 'bad'; }
      if ([1, 3, 6, 12, 18, 24].includes(ball)) await shot('after_ball_' + ball);
      continue;
    }
    if (st.cx !== null && prevCx !== null && st.cx !== prevCx && !hitThis) {
      if (MODE === 'bat') {
        if (mode === 'good' && st.zl !== null && st.cx >= st.zl + 2 && st.cx <= st.zr - 2) {
          await page.keyboard.press(CFG.keys[ball % CFG.keys.length]); hitThis = true;
          if (ball === 2) { await sleep(350); await shot('mid_shot'); }
        } else if (mode === 'bad') { await page.keyboard.press(CFG.keys[0]); hitThis = true; }
      } else { // bowling: release in zone
        if (st.zl !== null && st.cx >= st.zl + 2 && st.cx <= st.zr - 2) { await page.keyboard.press(CFG.bowlKey); hitThis = true; }
      }
    }
    prevCx = st.cx;
    // innings break / modal detection
    if (/innings|target|result|won|lost|all out/i.test(st.live) && /break|innings complete|all out|won|lost|match over/i.test(st.live)) { rows.push('EVENT: ' + st.live); }
    if (Date.now() - idleSince > 20000) { rows.push('STALL >20s; live=' + st.live + ' score=' + st.score + ' ov=' + st.ov); await shot('stall'); const t = await s.text(); rows.push('PAGE: ' + t.split('\n').filter(l => /innings|target|won|lost|all out|need|chase|continue|next|play/i.test(l)).slice(0, 12).join(' | ')); idleSince = Date.now(); if (rows.filter(r => r.startsWith('STALL')).length >= 3) break; }
    await sleep(8);
  }
  await shot('end');
  const final = await s.text();
  rows.push('FINAL PAGE LINES: ' + final.split('\n').filter(l => l.trim()).slice(0, 400).filter(l => /\d+\s*\/\s*\d+|innings|target|need|won|lost|over|result|wicket/i.test(l)).slice(0, 25).join(' | '));
  fs.writeFileSync(path.join(OUT, `${TAG}_${MODE}_${FORMAT}_play.txt`), rows.join('\n') + '\n\nLOG:\n' + log.join('\n'));
  console.log(rows.join('\n'));
  console.log(log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

