(async () => {
  const W = +WIDTH; const s = await open(ROOT, FILE, { width: W, height: W >= 1440 ? 900 : 800, sandbox: W < 1440 }); await sleep(2000);
  const { frame: f, page, log } = s; const rows = [];
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${PLAN}_${String(++n).padStart(2, '0')}_${name}.png`));
  const text = () => s.text();
  const live = () => f.evaluate(() => [...document.querySelectorAll('[role=status],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 160));
  // meter value 0..100
  const meterVal = TAG === 'A'
    ? () => f.evaluate(() => { const m = document.querySelector('[role=meter]'); return m ? +m.getAttribute('aria-valuenow') : -1; })
    : () => f.evaluate(() => { const n = document.querySelector('.meter-needle'); return n ? parseFloat(n.style.left) || -1 : -1; });
  const waitMeter = (lo, hi, timeout = 12000) => f.evaluate((TAG, lo, hi, timeout) => new Promise(r => {
    const t0 = performance.now(); const get = () => { if (TAG === 'A') { const m = document.querySelector('[role=meter]'); return m ? +m.getAttribute('aria-valuenow') : -1; } const n = document.querySelector('.meter-needle'); return n ? parseFloat(n.style.left) || -1 : -1; };
    const loop = () => { const v = get(); if (v >= lo && v <= hi) return r(v); if (performance.now() - t0 > timeout) return r('timeout'); requestAnimationFrame(loop); }; loop();
  }), TAG, lo, hi, timeout);
  const scoreLine = () => f.evaluate(() => { const sb = document.querySelector('.scoreboard'); return sb ? sb.innerText.replace(/\s+/g, ' ').slice(0, 120) : ''; });

  if (PLAN === 'odi') {
    await s.click({ text: 'ODI' }, 600); await s.click({ text: 'LET’S PLAY' }, 3500);
    rows.push('ODI scoreboard: ' + await scoreLine()); await shot('odi');
  }

  if (PLAN === 'A_full') {
    await s.click({ text: 'LET’S PLAY' }, 300);
    let balls = 0;
    // innings 1: early lofts
    while (balls < 90) {
      const v = await waitMeter(36, 44, 9000);
      if (v === 'timeout') { const t = await text(); if (/break|innings break|2nd innings|target/i.test(t) && !/1ST INNINGS/.test(await scoreLine())) break; rows.push('timeout waiting meter; scoreboard=' + await scoreLine()); const tt = t.split('\n').filter(l => /BREAK|INNINGS|TARGET|NEED|CHASE|DEFEND|SET/i.test(l)).slice(0, 8).join(' | '); rows.push('  page: ' + tt); break; }
      await page.keyboard.press('KeyD'); balls++;
      await sleep(1700);
      if (balls % 5 === 0) rows.push(`inn1 ball ${balls}: ${await scoreLine()} | ${await live()}`);
    }
    await sleep(1500); await shot('innings_break');
    rows.push('BREAK PAGE: ' + (await text()).split('\n').filter(l => l.trim()).filter(l => /BREAK|INNINGS|TARGET|NEED|DEFEND|runs|win|BOWL/i.test(l)).slice(0, 12).join(' | '));
    // continue to innings 2
    const btn = await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => b.getBoundingClientRect().width > 0 && /2nd innings|second innings|let.s bowl|start bowling|continue|take the field|next innings|innings/i.test(b.innerText)));
