const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3500);
  const { frame: f, page, log } = s;
  const cshot = async (name) => { const c = await f.$('canvas'); await c.evaluate(e => e.scrollIntoView({ block: 'center' })); const bb = await c.boundingBox(); await page.screenshot({ path: path.join(OUT, `${TAG}2_${name}.png`), clip: { x: Math.max(0, bb.x), y: Math.max(0, bb.y), width: Math.min(bb.width, 1000 - bb.x), height: Math.min(bb.height, 800 - Math.max(0, bb.y)) } }); };
  if (TAG === 'A') {
    await s.click({ label: 'Play animation' }, 200);
    for (let i = 0; i < 6; i++) { await cshot('play_' + i); log.push(`frame ${i}: ${await f.evaluate(() => (document.body.innerText.match(/(\d{3})° \/ 720°/) || [])[1])} stroke=${await f.evaluate(() => [...document.querySelectorAll('h2,h3')].map(h => h.innerText).find(t => /^(Intake|Compression|Power|Exhaust)\.$/.test(t)))}`); await sleep(700); }
    await s.click({ label: 'Pause animation' }, 300);
    // speed menu
    await s.click({ label: 'Animation speed: 1 times' }, 400);
    const opts = await f.evaluate(() => [...document.querySelectorAll('[role=menuitemradio],[role=option],[role=menuitem],button')].filter(b => /^(0\.5|1\.5|2)×$/.test(b.innerText.trim())).map(b => b.innerText.trim()));
    log.push('speed options: ' + JSON.stringify(opts));
    // slider drag
    const sl = await f.$('input[type=range]'); const bb = await sl.boundingBox();
    await page.mouse.click(bb.x + bb.width * 0.75, bb.y + bb.height / 2); await sleep(800);
    log.push('slider click at 75%: ' + await f.evaluate(() => (document.body.innerText.match(/(\d{3})° \/ 720°/) || [])[1]) + ' stroke=' + await f.evaluate(() => [...document.querySelectorAll('h2,h3')].map(h => h.innerText).find(t => /^(Intake|Compression|Power|Exhaust)\.$/.test(t))));
    await cshot('slider75');
  } else {
    await s.click({ label: 'Hide Main housing' }, 500); await s.click({ label: 'Hide Housing cover' }, 800);
    await s.click({ label: 'Play simulation' }, 300);
    for (let i = 0; i < 4; i++) { await cshot('sim_' + i); await sleep(600); }
    await s.click({ label: 'Pause simulation' }, 300);
    // material on selected gear pair
    const sel = (await f.$$('select')).find ? null : null;
    const sels = await f.$$('select'); let mat = null;
    for (const x of sels) { const o = await x.evaluate(e => [...e.options].map(o => o.text)); if (o.some(t => /brass/i.test(t))) mat = x; }
    if (mat) { const v = await mat.evaluate(e => [...e.options].find(o => /brass/i.test(o.text)).value); await mat.select(v); await sleep(1200); await cshot('brass'); log.push('material set to brass'); }
    // display tab switches
    await s.click({ text: 'Display', sel: 'button,[role=tab]' }, 600);
    const sw = await f.evaluate(() => [...document.querySelectorAll('[role=switch]')].map(e => `${e.getAttribute('aria-label') || e.closest('label,div')?.innerText.trim().slice(0, 25)}=${e.getAttribute('aria-checked')}`));
    log.push('display switches: ' + JSON.stringify(sw));
    const mp = (await f.evaluateHandle(() => [...document.querySelectorAll('[role=switch]')].find(e => /motion/i.test((e.getAttribute('aria-label') || '') + (e.closest('label,div')?.innerText || ''))))).asElement();
