const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1440, height: 900, sandbox: false }); await sleep(2500);
  const { frame: f, page, log } = s;
  const total = await f.evaluate(() => document.documentElement.scrollHeight);
  for (let y = 0; y < total; y += 400) { await f.evaluate(y => scrollTo(0, y), y); await sleep(150); }
  await sleep(800);
  const elShot = async (sel, name) => { const h = await f.$(sel); if (!h) { log.push('no ' + sel); return; } await h.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(900); await h.screenshot({ path: path.join(OUT, `${TAG}_${name}.png`) }); };
  if (TAG === 'A') {
    const stage = '#identity [role=tabpanel], #identity .logo-stage, #identity .identity-stage';
    const pick = async () => await f.evaluate(() => { const c = [...document.querySelectorAll('#identity *')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 700 && r.height > 300 && r.height < 700 && getComputedStyle(e).backgroundColor !== 'rgba(0, 0, 0, 0)'; }); c.sort((a, b) => a.getBoundingClientRect().height - b.getBoundingClientRect().height); if (c[0]) c[0].setAttribute('data-stage', '1'); return c.length; });
    await pick();
    for (const [q, n] of [[{ text: 'Full signature' }, 'full'], [{ text: 'Wordmark' }, 'wordmark'], [{ text: 'Monogram' }, 'monogram']]) { await s.click(q, 900); await elShot('[data-stage]', 'stage_' + n); }
    await s.click({ text: 'Full signature' }, 800);
    await s.click({ label: 'Preview on white background' }, 900); await elShot('[data-stage]', 'stage_full_white');
    await s.click({ label: 'Antique brass finish' }, 900); await elShot('[data-stage]', 'stage_full_brass');
    // applications
    for (const t of ['Slides & grips', 'Luxury packaging', 'Engraving stamps', 'Uniforms']) {
      await s.click({ text: t }, 1200);
      await f.evaluate(() => { const c = [...document.querySelectorAll('#applications *')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 500 && r.height > 300; }); c.sort((a, b) => a.getBoundingClientRect().width * a.getBoundingClientRect().height - b.getBoundingClientRect().width * b.getBoundingClientRect().height); document.querySelectorAll('[data-app]').forEach(x => x.removeAttribute('data-app')); const big = c.find(e => e.querySelector('svg,img')) || c[0]; if (big) big.setAttribute('data-app', '1'); });
      await elShot('#applications', 'app_' + t.split(' ')[0]);
    }
