const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const csv = path.join(OUT, 'contacts.csv'); fs.writeFileSync(csv, 'email,first_name,company\njane@test.com,Jane,Acme\nbob@test.com,Bob,Beta\nzoe@test.com,Zoe,Gamma\n');
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true });
  const { frame: f, page, log } = s;
  const reqs = [];
  page.on('request', r => { const u = r.url(); if (!/\.(html|css|js|svg|png|woff2?)(\?|$)|css2|favicon/.test(u) && !u.endsWith('/')) reqs.push(`${r.method()} ${u.replace(/^https?:\/\/[^/]+/, '')}${r.postData() ? ' body=' + (r.postData().length) + 'B' : ''}`); else if (r.method() === 'POST') reqs.push(`POST ${u.replace(/^https?:\/\/[^/]+/, '')} ct=${r.headers()['content-type']?.slice(0, 40)}`); });
  await sleep(3500);
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text();
  const diff = async (b) => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 6).join(' | ').slice(0, 260);
  const toast = () => f.evaluate(() => [...document.querySelectorAll('[role=status],[role=alert],[aria-live],[class*=toast i]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' || ').slice(0, 200));
  const nums = () => f.evaluate(() => { const t = document.body.innerText; return (t.match(/([\d,]+)\s*\/\s*([\d,]+)\s*\n?\s*emails/i) || t.match(/([\d,]+) of ([\d,]+) emails/i) || [''])[0].replace(/\s+/g, ' ') + ' | ' + (t.match(/(\d+\.\d)\s*%\s*\n?\s*completed/i) || [''])[0].replace(/\s+/g, ' '); });
  log.push('idle progress: ' + await nums() + ' reqs so far: ' + JSON.stringify(reqs.slice(0, 8)));
  // live updates while running (A starts RUNNING, B starts PAUSED)
  if (TAG === 'B') { await s.click({ text: 'Start sending' }, 800); log.push('after Start: toast=' + await toast()); }
  const p1 = await nums(); await sleep(4000); const p2 = await nums();
  log.push(`running progress: ${p1} -> ${p2}`);
  const feed1 = await f.evaluate(() => document.body.innerText.match(/Live activity[\s\S]{0,200}/)?.[0].replace(/\s+/g, ' ')); log.push('feed now: ' + feed1);
  await shot('running');
  // stop
  const b0 = await T(); await s.click({ text: 'Stop sending' }, 1200); log.push('Stop: +[' + await diff(b0) + '] toast=' + await toast());
  const p3 = await nums(); await sleep(3000); const p4 = await nums(); log.push(`after stop progress: ${p3} -> ${p4}`);
  await shot('stopped');
  log.push('API requests so far: ' + JSON.stringify([...new Set(reqs)].slice(0, 20)));
  // campaign selector
  const sel = await f.$('select[aria-label*="ampaign" i]') || (await f.$$('header select'))[0];
  if (sel) { const opts = await sel.evaluate(e => [...e.options].map(o => o.text)); const b = await T(); await sel.select(await sel.evaluate(e => e.options[1].value)); await sleep(1000); log.push('campaign select options ' + JSON.stringify(opts) + ' -> +[' + await diff(b) + ']'); }
  else { const b = await T(); await s.click({ label: 'Select campaign, October Outreach' }, 600); await s.click({ text: 'Product Launch' }, 1200); log.push('campaign menu -> Product Launch: +[' + await diff(b) + ']'); }
  // CSV upload
  const fi = await f.$('input[type=file]');
  if (fi) { const b = await T(); await fi.uploadFile(csv); await sleep(1500); log.push('CSV upload: +[' + await diff(b) + '] toast=' + await toast()); await shot('csv'); } else log.push('NO file input');
  // delay input
  const delay = await f.$('input[type=number]');
  if (delay) { await delay.click({ clickCount: 3 }); await page.keyboard.type('7'); await page.keyboard.press('Tab'); await sleep(500); log.push('delay now: ' + await delay.evaluate(e => e.value)); }
  // subjects: add one and type
  const countSubj = () => f.evaluate(() => [...document.querySelectorAll('input')].filter(i => /subject/i.test((i.getAttribute('aria-label') || '') + (i.placeholder || '') + (i.name || ''))).length);
  const sb = await countSubj(); await s.click({ text: 'Add subject' }, 700); const sa = await countSubj(); log.push(`subjects ${sb} -> ${sa}`);
  const subjInputs = await f.$$('input'); let lastSubj = null; for (const i of subjInputs) { if (await i.evaluate(e => /subject/i.test((e.getAttribute('aria-label') || '') + (e.placeholder || '') + (e.name || '')))) lastSubj = i; }
  if (lastSubj) { await lastSubj.click(); await page.keyboard.type('Big news for {{first_name}}'); await sleep(700); }
  // message: type into textarea and check preview
  const ta = await f.$('textarea');
  if (ta) { await ta.click({ clickCount: 3 }); await page.keyboard.press('Control+A'); await page.keyboard.type('Hello {{first_name}}, ZEBRA test line.'); await sleep(1000); log.push('preview shows ZEBRA: ' + await f.evaluate(() => [...document.querySelectorAll('*')].some(e => e.children.length === 0 && /ZEBRA/.test(e.textContent) && e.tagName !== 'TEXTAREA'))); log.push('preview personalised: ' + (await f.evaluate(() => (document.body.innerText.match(/Hello [A-Z][a-z]+, ZEBRA/) || [''])[0]))); }
  // templates
  const b5 = await T(); await s.click({ text: 'Add template' }, 700); log.push('Add template: +[' + await diff(b5) + ']');
  const tsel = await f.$('select[aria-label*="emplate" i], select[aria-label*="essage" i]');
  if (tsel) { const o = await tsel.evaluate(e => [...e.options].map(o => o.text)); await tsel.select(await tsel.evaluate(e => e.options[e.options.length - 1].value)); await sleep(700); log.push('template select ' + JSON.stringify(o) + ' textarea now: ' + (await ta.evaluate(e => e.value.slice(0, 60)))); }
  await shot('builder');
  // review / start campaign from builder
  for (const q of [{ text: 'Review campaign' }, { text: 'Save draft' }, { text: 'Send a test' }, { text: 'Full preview' }]) { const b = await T(); const el = await s.click(q, 1200); if (el) log.push(`${q.text}: +[${await diff(b)}] toast=${await toast()}`); await page.keyboard.press('Escape'); await sleep(400); }
  // logs filter & search
  const lsel = (await f.$$('select')).length; log.push('select count ' + lsel);
  const search = await f.$('input[type=search], input[placeholder*="earch" i]');
  if (search) { await search.click(); await page.keyboard.type('olivia'); await sleep(900); log.push('log search olivia rows: ' + await f.evaluate(() => [...document.querySelectorAll('tbody tr')].filter(r => r.getBoundingClientRect().height > 0).map(r => r.innerText.replace(/\s+/g, ' ').slice(0, 40)).join(' / '))); }
  // dark mode
  const bg1 = await f.evaluate(() => getComputedStyle(document.body).backgroundColor + ' / ' + getComputedStyle(document.querySelector('main') || document.body).backgroundColor);
  const dm = await s.click({ label: TAG === 'A' ? 'Toggle dark mode' : 'Switch to light mode' }, 900);
  const bg2 = await f.evaluate(() => getComputedStyle(document.body).backgroundColor + ' / ' + getComputedStyle(document.querySelector('main') || document.body).backgroundColor);
  log.push(`theme toggle: ${bg1} -> ${bg2}`); await shot('theme');
  // glass check
  log.push('backdrop-filter cards: ' + await f.evaluate(() => [...document.querySelectorAll('*')].filter(e => { const b = getComputedStyle(e).backdropFilter; return b && b !== 'none'; }).length));
  // help / flask instructions
  for (const q of TAG === 'A' ? [{ text: 'Connect Flask' }, { text: 'Help & documentation' }] : [{ text: 'Need a hand?' }]) { const el = await s.click(q, 1000); if (el) log.push(`${q.text} dialog: ` + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 600))))); await page.keyboard.press('Escape'); await sleep(400); }
  log.push('ALL API requests: ' + JSON.stringify([...new Set(reqs)]));
  fs.writeFileSync(path.join(OUT, `${TAG}_dash.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404|status of 404/.test(l)).join('\n'));
  await s.close();
})();

