const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 7).join(' | ').slice(0, 300);
  const step = async (q, wait = 900) => { const b = await T(); const y0 = await f.evaluate(() => scrollY); const el = await s.click(q, wait); log.push(`${JSON.stringify(q)} found=${!!el} scroll ${y0}->${await f.evaluate(() => scrollY)} +[${await diff(b)}]`); return el; };
  // chart hover
  const hov = async (label) => {
    const svg = await f.evaluateHandle(() => { const c = [...document.querySelectorAll('svg')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 300 && r.height > 120; }); c.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top); return c[0]; });
    const el = svg.asElement(); if (!el) { log.push('no chart svg'); return; }
