  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 8).join(' | ').slice(0, 350);
  const charts = () => f.evaluate(() => [...document.querySelectorAll('svg')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 300 && r.height > 120; }).map((e, i) => { e.setAttribute('data-chart', i); const r = e.getBoundingClientRect(); return `${i}@${Math.round(r.top + scrollY)}`; }));
  const hoverChart = async (i, label) => { const el = await f.$(`[data-chart="${i}"]`); await el.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(400); const bb = await el.boundingBox(); const b = await T(); await s.hover(bb.x + bb.width * 0.7, bb.y + bb.height * 0.5, 700); log.push(`hover chart ${label}: +[${await diff(b)}]`); await shot('hover_' + label); await s.hover(2, 2, 200); };
  if (TAG === 'A') {
    const b0 = await T(); const help = await f.$('button[aria-label="Help and methodology"]'); const bb = await help.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1000);
    log.push(`help ? button: url=${await f.evaluate(() => location.hash)} +[${await diff(b0)}] dialogs=${await f.evaluate(() => document.querySelectorAll('[role=dialog]').length)}`); await shot('help');
    await page.keyboard.press('Escape'); await sleep(300);
    await s.click({ text: 'Overview' }, 800);
    await s.click({ text: '2030 forecast' }, 1500); await shot('forecast_top');
    log.push('forecast page text: ' + (await T()).split('\n').filter(l => l.trim()).slice(0, 60).join(' | ').slice(0, 900));
