    const c = await charts(); log.push('charts: ' + c); if (c.length) await hoverChart(c.length - 1, 'forecast');
    await shot('forecast_end');
  } else {
    const b = await T(); await s.click({ text: 'USD' }, 600); const opt = await f.evaluateHandle(() => [...document.querySelectorAll('button,[role=option],[role=menuitemradio],li')].find(e => /EUR/.test(e.innerText) && e.getBoundingClientRect().width > 0 && e.innerText.length < 30)); const el = opt.asElement();
    if (el) { const bb = await el.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(900); log.push('EUR picked: +[' + await diff(b) + ']'); } else log.push('EUR option not found');
    const c = await charts(); log.push('charts: ' + c); if (c.length > 1) await hoverChart(c.length - 1, 'forecast');
    await shot('eur');
  }
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

