const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(2500);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text();
  // state reader
  if (TAG === 'B') {
    await f.evaluate(() => {
      window.__game = () => {
        if (window.__g) return window.__g;
        const c = document.querySelector('canvas'); const key = Object.keys(c).find(k => k.startsWith('__reactFiber')); let fb = c[key];
        while (fb) { let h = fb.memoizedState; while (h) { const v = h.memoizedState; if (v && v.current && v.current.pipes && v.current.bird) { window.__g = v.current; return v.current; } h = h.next; } fb = fb.return; }
        return null;
      };
    });
  }
  const state = () => f.evaluate((TAG) => {
    if (TAG === 'A') {
      const b = document.querySelector('.flying-oli'); if (!b) return null; const br = b.getBoundingClientRect();
      const bx = br.x + br.width / 2, by = br.y + br.height / 2;
      const cols = [...document.querySelectorAll('.pipe-column:not(.pipe-preview)')].map(c => { const t = c.querySelector('.pipe-top').getBoundingClientRect(), bo = c.querySelector('.pipe-bottom').getBoundingClientRect(); return { l: t.x, r: t.x + t.width, gt: t.bottom, gb: bo.top }; }).filter(p => p.r > bx - 30).sort((a, b) => a.l - b.l);
      const p = cols[0]; return { by, target: p ? (p.gt + p.gb) / 2 + 6 : null, gap: p ? p.gb - p.gt : null };
    } else {
      const g = window.__game(); if (!g) return null;
      const p = g.pipes.filter(p => p.x + 70 > g.bird.x - 20).sort((a, b) => a.x - b.x)[0];
      return { by: g.bird.y, target: p ? p.center + 8 : null, gap: p ? p.gap : null, vel: g.bird.velocity, status: g.status, score: g.score };
    }
  }, TAG);
  const score = () => f.evaluate(() => { const t = document.body.innerText; const m = t.match(/SCORE\s*\n\s*(\d+)/i); const b = t.match(/BEST\s*\n\s*(\d+)/i); return `score=${m ? m[1] : '?'} best=${b ? b[1] : '?'}`; });
  await s.click({ text: TAG === 'A' ? 'START GAME' : "Let's fly" }, 100);
  const t0 = Date.now(); let last = ''; let lastFlap = 0; let flaps = 0;
  while (Date.now() - t0 < 40000) {
    const st = await state();
    if (st && st.target !== null) {
      if (st.by > st.target && Date.now() - lastFlap > (TAG === 'A' ? 170 : 170)) { await page.keyboard.press('Space'); lastFlap = Date.now(); flaps++; }
    } else if (st && st.by > 300 && Date.now() - lastFlap > 250) { await page.keyboard.press('Space'); lastFlap = Date.now(); }
    const sc = await score(); if (sc !== last) { log.push(`${((Date.now() - t0) / 1000).toFixed(1)}s ${sc}`); last = sc; if (/score=3 /.test(sc)) await shot('playing'); }
    if (/score=(1[2-9]|[2-9]\d) /.test(sc)) break;
    const txt = await T(); if (/again|crash|Game over|One more flight/i.test(txt) && !/ready/i.test(await f.evaluate(() => document.querySelector('[aria-live]')?.innerText || ''))) { if (/Game over|again/i.test(txt.split('\n').slice(0, 60).join(' '))) {} }
    await sleep(15);
  }
  log.push(`flaps=${flaps}`);
  // pause
  await page.keyboard.press('KeyP'); await sleep(700); const p1 = await state(); await sleep(1000); const p2 = await state();
  log.push(`pause P: bird moved ${p1 && p2 ? Math.round(Math.abs(p2.by - p1.by)) : '?'}px; live="${await f.evaluate(() => [...document.querySelectorAll('[aria-live]')].map(e => e.innerText).join(' ').slice(0, 80))}"`); await shot('paused');
  await page.keyboard.press('KeyP'); await sleep(300);
  // crash: stop flapping
  const t1 = Date.now(); while (Date.now() - t1 < 8000) { await sleep(200); const live = await f.evaluate(() => [...document.querySelectorAll('[aria-live]')].map(e => e.innerText).join(' ')); if (/over|crash/i.test(live) || /One more flight|Play again|Try again/i.test(await T())) break; }
  await sleep(1200); await shot('gameover');
  log.push('game over screen: ' + (await T()).split('\n').filter(l => l.trim()).slice(0, 80).join(' | ').match(/(SCORE[\s\S]*)/)?.[0].slice(0, 400));
  // restart via R
  await page.keyboard.press('KeyR'); await sleep(800); log.push('after R: ' + await score() + ' live=' + await f.evaluate(() => [...document.querySelectorAll('[aria-live]')].map(e => e.innerText).join(' ').slice(0, 60)));
  // reload best
  await f.evaluate(() => location.reload()); await sleep(3000);
  const f2 = page.frames().find(x => x !== page.mainFrame());
  log.push('after reload: ' + await f2.evaluate(() => { const t = document.body.innerText; const b = t.match(/BEST\s*\n\s*(\d+)/i); return 'best=' + (b ? b[1] : '?'); }));
  fs.writeFileSync(path.join(OUT, `${TAG}_flap.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

