const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 10).join(' | ').slice(0, 450);
  const dlg = () => f.evaluate(() => [...document.querySelectorAll('[role=dialog],[role=alertdialog]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 500)));
  const toast = () => f.evaluate(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 250));
  // list slot label samples
  const labels = await f.evaluate(() => [...document.querySelectorAll('button[aria-label]')].map(b => b.getAttribute('aria-label')).filter(l => /\d\d:\d\d/.test(l)));
  log.push('slot label samples: ' + JSON.stringify(labels.filter((_, i) => i % 97 === 0).slice(0, 10)) + ' total=' + labels.length);
  const findSlot = (res, time) => f.evaluateHandle((res, time) => { const bs = [...document.querySelectorAll('button[aria-label]')]; return bs.find(b => { const l = b.getAttribute('aria-label'); return l.includes(res) && (l.includes(time + ' to') || l.includes('at ' + time) || l.includes(time + ',') || l.endsWith(time)); }) || null; }, res, time);
  const clickSlot = async (res, time, name) => {
    const h = (await findSlot(res, time)).asElement(); if (!h) { log.push(`slot ${res} ${time} NOT FOUND`); return false; }
    const lab = await h.evaluate(e => e.getAttribute('aria-label') + (e.disabled ? ' [disabled]' : '') + ' aria-disabled=' + e.getAttribute('aria-disabled'));
    await h.evaluate(e => e.scrollIntoView({ block: 'center', inline: 'center' })); await sleep(300);
    const bb = await h.boundingBox(); const b = await T();
    await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1000);
    log.push(`click slot [${lab}] -> +[${await diff(b)}] dialogs=${JSON.stringify(await dlg()).slice(0, 500)} toast=${await toast()}`);
    await shot(name); return true;
  };
  const dialogControls = () => f.evaluate(() => { const d = [...document.querySelectorAll('[role=dialog]')].pop(); if (!d) return null; return [...d.querySelectorAll('input,select,button,textarea')].map(e => `${e.tagName}${e.type ? '[' + e.type + ']' : ''}:${(e.getAttribute('aria-label') || e.name || e.id || e.innerText || '').trim().replace(/\s+/g, ' ').slice(0, 25)}=${(e.value || '').slice(0, 15)}${e.tagName === 'SELECT' ? '{' + [...e.options].map(o => o.text).slice(0, 6).join('/') + '}' : ''}`); });
  const confirm = async () => { const b = await T(); const h = (await f.evaluateHandle(() => { const d = [...document.querySelectorAll('[role=dialog]')].pop(); if (!d) return null; const bs = [...d.querySelectorAll('button')].filter(x => x.getBoundingClientRect().width > 0 && !/cancel|close/i.test(x.innerText + (x.getAttribute('aria-label') || ''))); return bs.find(x => /book|reserve|confirm|save|add/i.test(x.innerText)) || bs.pop(); })).asElement(); if (!h) return 'no confirm'; const t = await h.evaluate(e => e.innerText.trim() + (e.disabled ? ' [disabled]' : '')); const bb = await h.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1200); return `confirm "${t}" -> +[${await diff(b)}] dialogs=${JSON.stringify(await dlg()).slice(0, 300)} toast=${await toast()}`; };
  const setSelect = async (re, valRe) => { return f.evaluate((re, valRe) => { const d = [...document.querySelectorAll('[role=dialog]')].pop(); const sels = [...d.querySelectorAll('select')]; const s = sels.find(x => new RegExp(re, 'i').test((x.getAttribute('aria-label') || '') + x.name + x.id + (x.labels && x.labels[0] ? x.labels[0].innerText : ''))); if (!s) return 'no select ' + re; const o = [...s.options].find(o => new RegExp(valRe).test(o.text)); if (!o) return 'no option ' + valRe; const setter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set; setter.call(s, o.value); s.dispatchEvent(new Event('change', { bubbles: true })); return 'set ' + re + '=' + o.text; }, re, valRe); };

  // 1. appliance slot where room NOT booked (12:15 is between bookings on both)
  const app = TAG === 'A' ? 'Convection oven' : 'Oven';
  await clickSlot(app, '12:15', 'appliance_unbooked'); await page.keyboard.press('Escape'); await sleep(400);
  // 2. main room free slot 21:00 (A free after 20:00; B free after 21:00 -> use 22:00)
  await clickSlot('Main room', '22:00', 'room_dialog');
  log.push('room dialog controls: ' + JSON.stringify(await dialogControls()));
  log.push('room end: ' + await setSelect('end|to|until', '23:00'));
  log.push('room confirm: ' + await confirm()); await shot('room_booked');
  // 3. appliance inside new room booking 22:00
  await clickSlot(app, '22:00', 'appliance_dialog');
  log.push('appliance dialog controls: ' + JSON.stringify(await dialogControls()));
  log.push('appliance end beyond room: ' + await setSelect('end|to|until', '23:30'));
  log.push('dialog after beyond-room end: ' + JSON.stringify(await dlg()).slice(0, 400));
  log.push('appliance end inside: ' + await setSelect('end|to|until', '22:30'));
  log.push('appliance confirm: ' + await confirm()); await shot('appliance_booked');
  // show booking block text
  log.push('timeline now has 22:00: ' + await f.evaluate(() => [...document.querySelectorAll('*')].filter(e => e.children.length < 4 && /22:00\s*-\s*2[23]:\d\d/.test(e.innerText || '')).map(e => e.innerText.replace(/\s+/g, ' ')).slice(0, 6).join(' / ')));
  // 4. overlap: same appliance 22:15
  await clickSlot(app, '22:15', 'overlap'); await page.keyboard.press('Escape'); await sleep(400);
  fs.writeFileSync(path.join(OUT, `${TAG}_book.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

