  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 10).join(' | ').slice(0, 400);
  const dlgOpen = () => f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].some(d => d.getBoundingClientRect().width > 0));
  const dlgText = () => f.evaluate(() => { const d = [...document.querySelectorAll('[role=dialog]')].pop(); if (!d) return ''; const t = d.innerText.replace(/\s+/g, ' '); return t.replace(/(\d\d:\d\d ){4,}[\d: ()a-z]*/g, '[times] ').slice(0, 600); });
  const toast = () => f.evaluate(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 250));
  const waitToastGone = async () => { for (let i = 0; i < 20; i++) { if (!(await toast())) return; await sleep(500); } };
  const sel = async (re, txt) => { const h = (await f.evaluateHandle((re) => { const d = [...document.querySelectorAll('[role=dialog]')].pop(); return [...d.querySelectorAll('select')].find(x => new RegExp(re, 'i').test((x.getAttribute('aria-label') || '') + x.name + x.id)); }, re)).asElement(); if (!h) return 'no select ' + re; const v = await h.evaluate((e, txt) => { const o = [...e.options].find(o => o.text.startsWith(txt)); return o ? o.value : null; }, txt); if (v === null) return 'no option ' + txt; await h.select(v); await sleep(400); return `${re}=${txt}`; };
  const clickBtn = async (re) => { const h = (await f.evaluateHandle((re) => { const d = [...document.querySelectorAll('[role=dialog]')].pop() || document; return [...d.querySelectorAll('button')].find(b => new RegExp(re, 'i').test(b.innerText) && b.getBoundingClientRect().width > 0); }, re)).asElement(); if (!h) return 'no button ' + re; const bb = await h.boundingBox(); const top = await h.evaluate(e => { const r = e.getBoundingClientRect(); const t = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2); return t === e || e.contains(t) ? 'ok' : 'COVERED by ' + (t ? t.innerText?.slice(0, 40) : '?'); }); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1200); return `clicked "${re}" (${top})`; };
  const openNew = async () => { await f.evaluate(() => scrollTo(0, 0)); await sleep(300); const h = (await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => /New booking/.test(b.innerText) && b.getBoundingClientRect().width > 0))).asElement(); const bb = await h.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(900); };
  const app = TAG === 'A' ? 'Convection oven' : 'Oven';
  // room booking 22:00-23:00
  await openNew();
  if (TAG === 'B') await clickBtn('^\\s*Main room\\s*$');
  log.push(await sel('resource', 'Main room')); log.push(await sel('start', '22:00')); log.push(await sel('end', '23:00'));
  log.push('room: ' + await clickBtn(TAG === 'A' ? 'Create booking' : 'Confirm booking') + ' toast=' + await toast() + ' dialogOpen=' + await dlgOpen());
  await waitToastGone();
  // appliance beyond room end
  await openNew();
  if (TAG === 'B') await clickBtn('^\\s*Appliance\\s*$');
  log.push(await sel('resource', app)); log.push(await sel('start', '22:00')); log.push(await sel('end', '23:30'));
  log.push('dialog with end 23:30: ' + await dlgText()); await shot('beyond_room');
  log.push('beyond-room confirm: ' + await clickBtn(TAG === 'A' ? 'Create booking' : 'Confirm booking') + ' toast=' + await toast() + ' dialogOpen=' + await dlgOpen());
  if (await dlgOpen()) { log.push('dialog after: ' + await dlgText()); await shot('beyond_room_after'); }
  // fix to inside
  if (await dlgOpen()) { log.push(await sel('end', '22:30')); log.push('inside confirm: ' + await clickBtn(TAG === 'A' ? 'Create booking' : 'Confirm booking') + ' toast=' + await toast() + ' dialogOpen=' + await dlgOpen()); }
  await waitToastGone(); await shot('after_appliance');
  log.push('row shows: ' + await f.evaluate(() => [...document.querySelectorAll('button[aria-label], [title]')].map(b => b.getAttribute('aria-label') || b.getAttribute('title')).filter(l => /22:00\s*-\s*22:30|22:00 - 22:30/.test(l)).slice(0, 3).join(' / ')));
  // overlap: same appliance 22:15-22:45
  await openNew(); if (TAG === 'B') await clickBtn('^\\s*Appliance\\s*$');
  log.push(await sel('resource', app)); log.push(await sel('start', '22:15')); log.push(await sel('end', '22:45'));
  log.push('overlap dialog: ' + (await dlgText()).slice(-260));
  log.push('overlap confirm: ' + await clickBtn(TAG === 'A' ? 'Create booking' : 'Confirm booking') + ' toast=' + await toast() + ' dialogOpen=' + await dlgOpen());
  await shot('overlap'); await page.keyboard.press('Escape'); await sleep(500); await waitToastGone();
  // delete the room booking that contains the appliance booking
  const roomBlock = (await f.evaluateHandle(() => [...document.querySelectorAll('button,[role=button]')].find(b => /22:00\s*-\s*23:00/.test((b.getAttribute('aria-label') || '') + b.innerText) && /Main room|room/i.test((b.getAttribute('aria-label') || '') + b.closest('[class]')?.className)))).asElement();
  if (roomBlock) { await roomBlock.evaluate(e => e.scrollIntoView({ block: 'center', inline: 'center' })); await sleep(400); const bb = await roomBlock.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(900); log.push('room block dialog: ' + await dlgText()); await shot('room_details');
    log.push('delete: ' + await clickBtn('Delete|Cancel booking|Remove')); log.push('after delete click dialog: ' + await dlgText());
    if (await dlgOpen()) { log.push('confirm delete: ' + await clickBtn('Delete|Remove|Yes|Cancel booking')); }
    await sleep(800); log.push('after delete toast=' + await toast()); await shot('after_delete');
    log.push('appliance 22:00 booking still there? ' + await f.evaluate(() => /22:00\s*-\s*22:30/.test(document.body.innerText)));
  } else log.push('room block not found');
  // day nav
  const b0 = await T(); await f.evaluate(() => scrollTo(0, 0)); await s.click({ label: 'Next day' }, 900); log.push('next day: +[' + await diff(b0) + ']'); await shot('next_day');
  fs.writeFileSync(path.join(OUT, `${TAG}_book2.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

