const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l) && !/\d+s ago|Updated|synced|^\d\d:\d\d$/.test(l)).slice(0, 10).join(' | ').slice(0, 380);
  const dlg = () => f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 700)).join(' ## '));
  const toast = () => f.evaluate(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(t => t && !/ago$/.test(t)))].join(' || ').slice(0, 200));
  const rows = () => f.evaluate(() => [...document.querySelectorAll('tbody tr')].filter(r => r.getBoundingClientRect().height > 0).map(r => r.innerText.replace(/\s+/g, ' ').trim().slice(0, 50)).slice(0, 6));
  const step = async (q, w = 900, nm) => { const b = await T(); const el = await s.click(q, w); log.push(`${JSON.stringify(q)} found=${!!el} +[${await diff(b)}] toast=${await toast()}`); if (nm) await shot(nm); return el; };
  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };
  // leaderboard sort
  log.push('rows initial: ' + JSON.stringify(await rows()));
  await step(TAG === 'A' ? { text: 'Win rate', sel: 'button,th' } : { label: 'Sort by Win rate' }); log.push('rows after win-rate sort: ' + JSON.stringify(await rows()));
  await step(TAG === 'A' ? { text: 'Max. drawdown', sel: 'button,th' } : { label: 'Sort by Max drawdown' }); log.push('rows after DD sort: ' + JSON.stringify(await rows()));
  // market filter
  const ms = await f.$('select[aria-label="Filter by market"]'); if (ms) { await ms.select(await ms.evaluate(e => [...e.options].find(o => /Forex/.test(o.text)).value)); await sleep(800); log.push('market=Forex rows: ' + JSON.stringify(await rows())); await ms.select(await ms.evaluate(e => e.options[0].value)); await sleep(600); }
  // filters panel
  await step({ text: 'Filters' }, 900, 'filters');
  log.push('filters panel: ' + (await dlg() || (await f.evaluate(() => { const p = [...document.querySelectorAll('[role=dialog],[role=menu],[class*=popover i],[class*=filter i]')].filter(e => e.getBoundingClientRect().width > 150 && e.getBoundingClientRect().height > 100).pop(); return p ? p.innerText.replace(/\s+/g, ' ').slice(0, 600) : 'none'; }))));
  log.push('filter inputs: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('input[type=range],input[type=number]')].filter(e => e.getBoundingClientRect().width > 0).map(e => (e.getAttribute('aria-label') || e.id || e.name) + '=' + e.value))));
  const rng = (await f.$$('input[type=range],input[type=number]'))[0];
  if (rng) { const bb = await rng.boundingBox(); if (bb) { if (await rng.evaluate(e => e.type) === 'range') await page.mouse.click(bb.x + bb.width * 0.7, bb.y + bb.height / 2); else { await rng.click({ clickCount: 3 }); await page.keyboard.type('70'); } await sleep(700); const ap = await s.find({ text: 'Apply' }); if (ap) await s.click({ text: 'Apply' }, 800); log.push('after first filter change rows: ' + JSON.stringify(await rows()) + ' count text: ' + await f.evaluate(() => (document.body.innerText.match(/Showing[\s\S]{0,30}strategies|\d+ strategies/) || [''])[0].replace(/\s+/g, ' '))); await shot('filtered'); } }
  const reset = await s.find({ text: 'Reset' }) || await s.find({ text: 'Clear' }); if (reset) await s.click(reset ? { text: (await reset.evaluate(e => e.innerText.trim())) } : {}, 600);
  await esc();
  // pause scanner and check labels
  const live1 = async () => f.evaluate(() => [...document.querySelectorAll('*')].filter(e => e.children.length === 0 && /^(Live|Running|Scanner is running|Scanning|Paused|All systems scanning|Live trade feed)$/i.test(e.innerText?.trim() || '') && e.getBoundingClientRect().width > 0).map(e => e.innerText.trim()).join(','));
  log.push('labels before pause: ' + await live1());
  await step({ text: TAG === 'A' ? 'Pause scanner' : 'Pause scanning', sel: 'button' }, 1500, 'paused');
  if (TAG === 'B') { const pb = await s.find({ label: 'Pause scanning' }); if (pb) await step({ label: 'Pause scanning' }, 1500, 'paused2'); }
  log.push('labels after pause: ' + await live1());
  const feed1 = await f.evaluate(() => document.body.innerText.match(/(Live trade feed|Live trades)[\s\S]{0,160}/)?.[0].replace(/\s+/g, ' ')); await sleep(6000); const feed2 = await f.evaluate(() => document.body.innerText.match(/(Live trade feed|Live trades)[\s\S]{0,160}/)?.[0].replace(/\s+/g, ' '));
  log.push(`feed during pause changed? ${feed1 !== feed2}`);
  await step({ text: TAG === 'A' ? 'Resume scanner' : 'Resume', sel: 'button' }, 1200); if (TAG === 'B') { const rb = await s.find({ label: 'Resume scanning' }); if (rb) await step({ label: 'Resume scanning' }, 1200); }
  log.push('labels after resume: ' + await live1());
  // data source
  await step({ text: TAG === 'A' ? 'Paper environment' : 'Paper trading', sel: 'button' }, 800, 'datasource'); log.push('datasource menu: ' + await f.evaluate(() => document.body.innerText.match(/(Market data source|Data source|DATA SOURCE)[\s\S]{0,300}/i)?.[0].replace(/\s+/g, ' ')));
  await step({ text: 'Historical' }, 1000); await esc();
  // strategy details
  await f.evaluate(() => scrollTo(0, 0));
  await step({ text: TAG === 'A' ? 'Momentum Alpha' : '01 Momentum Pro', sel: 'button,tr,td' }, 1200, 'details');
  log.push('details: ' + (await dlg()).slice(0, 900));
  await esc();
  // compare: tick two
  const cbs = await f.$$('input[type=checkbox][aria-label*="ompare" i], input[type=checkbox][aria-label^="Select "]'); log.push('compare checkboxes: ' + cbs.length);
  for (const cb of cbs.filter((_, i) => TAG === 'B' ? i > 0 : true).slice(0, 2)) { await cb.evaluate(e => e.scrollIntoView({ block: 'center' })); const bb = await cb.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(400); }
  await step({ text: 'Compare', sel: 'button' }, 1200, 'compare'); log.push('compare view: ' + (await dlg()).slice(0, 700)); await esc();
  fs.writeFileSync(path.join(OUT, `${TAG}_trade.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

