const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}c_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l) && !/^\d\d:\d\d$/.test(l)).slice(0, 10).join(' | ').slice(0, 400);
  const dlg = () => f.evaluate(() => [...document.querySelectorAll('[role=dialog],[role=menu],[role=listbox]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 400)).join(' ## '));
  const toast = () => f.evaluate(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 200));
  const imgs = () => f.evaluate(() => [...document.querySelectorAll('img')].filter(i => i.getBoundingClientRect().width > 0).map(i => `${(i.alt || '').slice(0, 30)}:${i.complete && i.naturalWidth > 0 ? 'ok' : 'BROKEN'}`).join(', '));
  const progress = () => f.evaluate(() => (document.body.innerText.match(/\d+ of \d+ pieces( placed)?/) || [''])[0]);
  const step = async (q, nm, w = 1000) => { const b = await T(); const el = await s.click(q, w); log.push(`${JSON.stringify(q)} found=${!!el} +[${await diff(b)}] dlg=${(await dlg()).slice(0, 300)} toast=${await toast()} imgs=[${await imgs()}]`); if (nm) await shot(nm); return el; };
  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };
  log.push('imgs at load: ' + await imgs());
  if (TAG === 'A') {
    await step({ text: 'Hint' }, 'hint', 1500);
    await step({ text: 'Guide' }, 'guide');
    await step({ text: 'Preview' }, 'preview'); await esc();
    await step({ text: 'Medium' }, 'medium'); log.push('medium: ' + await progress());
    await step({ text: 'Hard' }, 'hard'); log.push('hard: ' + await progress());
    await step({ text: 'Easy' });
    await step({ text: 'Mix things up' });
    await step({ label: 'Somewhere, slowly A little change of scenery' }, 'scenery'); const opts = await dlg(); log.push('scenery menu: ' + opts);
    const other = await f.evaluate(() => [...document.querySelectorAll('[role=menu] button,[role=listbox] [role=option],[role=dialog] button, [role=menuitemradio]')].map(b => b.innerText.trim().replace(/\s+/g, ' ')).filter(t => t && !/Somewhere, slowly/.test(t)).slice(0, 6));
    log.push('other scenes: ' + JSON.stringify(other));
    if (other[0]) { await step({ text: other[0].split(' ').slice(0, 2).join(' ') }, 'scene2', 1500); }
    await esc();
    await step({ text: 'A new little puzzle' }, 'newpuzzle', 1500);
    await step({ text: 'How to play' }); await esc();
    await step({ text: 'Our little story' }); await esc();
  } else {
    await step({ text: 'A little hint' }, 'hint', 1500);
    await step({ label: 'Image guide' }, 'guide');
    await step({ label: 'Preview the complete puzzle image' }, 'preview'); await esc();
