const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(4000);
  const { frame: f, page, log } = s;
  const fails = [];
  page.on('response', r => { if (r.status() >= 400) fails.push(r.status() + ' ' + decodeURIComponent(r.url()).replace(/^https?:\/\/[^/]+/, '')); });
  const fb = await (await f.frameElement()).boundingBox();
  const H = await f.evaluate(() => document.documentElement.scrollHeight);
  log.push('doc height ' + H);
  let i = 0;
  for (let y = 0; y < H && i < 16; y += 700, i++) {
    // use real wheel scrolling so scroll-driven effects run
    await page.mouse.move(fb.x + 500, fb.y + 400);
    const cur = await f.evaluate(() => scrollY);
    let tries = 0; while ((await f.evaluate(() => scrollY)) < y - 5 && tries < 20) { await page.mouse.wheel({ deltaY: 350 }); await sleep(120); tries++; }
    await sleep(1600);
    const sy = await f.evaluate(() => Math.round(scrollY));
    const broken = await f.evaluate(() => [...document.querySelectorAll('img')].filter(im => { const r = im.getBoundingClientRect(); return r.bottom > 0 && r.top < innerHeight && r.width > 20; }).map(im => `${(im.getAttribute('src') || '').split('/').pop().slice(0, 24)}:${im.complete && im.naturalWidth > 0 ? 'ok' : 'BROKEN'}`).join(', '));
    log.push(`shot ${i} y=${sy} imgs in view: ${broken}`);
    await s.shot(path.join(OUT, `${TAG}_s${String(i).padStart(2, '0')}.png`));
  }
  log.push('HTTP fails: ' + JSON.stringify([...new Set(fails)]));
  log.push('all imgs: ' + await f.evaluate(() => [...document.querySelectorAll('img')].map(im => `${(im.getAttribute('src') || '').split('/').pop().slice(0, 24)}:${im.complete && im.naturalWidth > 0 ? 'ok' : 'BROKEN'}`).join(', ')));
  log.push('bg images: ' + await f.evaluate(() => [...new Set([...document.querySelectorAll('*')].map(e => getComputedStyle(e).backgroundImage).filter(b => b && b.includes('url(')).map(b => b.match(/url\("?([^")]+)/)[1].split('/').pop()))].join(', ')));
  fs.writeFileSync(path.join(OUT, `${TAG}_scroll.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|status of 404|CORS|ERR_FAILED/.test(l)).join('\n'));
  await s.close();
})();

