const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path'); const crypto = require('crypto');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(4000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}r_${String(++n).padStart(2, '0')}_${name}.png`));
  const fb = await (await f.frameElement()).boundingBox();
  const T = () => s.text();
  const hash = async (clip) => crypto.createHash('md5').update(await page.screenshot({ clip })).digest('hex').slice(0, 8);
  const ev = (fn, ...a) => Promise.race([f.evaluate(fn, ...a), new Promise(r => setTimeout(() => r('TIMEOUT'), 8000))]);
  // particles: canvas changes over time
  const cv = await ev(() => { const c = document.querySelector('canvas'); if (!c) return null; const r = c.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, pos: getComputedStyle(c).position, z: getComputedStyle(c).zIndex }; });
  log.push('canvas: ' + JSON.stringify(cv));
  const clip = { x: fb.x + 600, y: fb.y + 500, width: 300, height: 200 };
  const h1 = await hash(clip); await sleep(1200); const h2 = await hash(clip); log.push(`hero area animating (particles etc): ${h1 !== h2}`);
  // custom cursor
  await page.mouse.move(fb.x + 300, fb.y + 300); await sleep(300); await page.mouse.move(fb.x + 420, fb.y + 360, { steps: 6 }); await sleep(500);
  const cur = await ev(() => { const cands = [...document.querySelectorAll('[class*=cursor i],[id*=cursor i]')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.width < 80; }); const bc = getComputedStyle(document.body).cursor + '/' + getComputedStyle(document.documentElement).cursor; return { bodyCursor: bc, els: cands.map(e => { const r = e.getBoundingClientRect(); return `${(e.className.baseVal ?? e.className).toString().slice(0, 30)}@${Math.round(r.x + r.width / 2)},${Math.round(r.y + r.height / 2)} ${Math.round(r.width)}px op=${getComputedStyle(e).opacity}`; }) }; });
  log.push('cursor (mouse at 420,360): ' + JSON.stringify(cur));
  // hero text rotation with cursor
  const heroT = () => ev(() => { const h = document.querySelector('h1'); const chain = []; let e = h; for (let i = 0; i < 4 && e; i++, e = e.parentElement) chain.push(getComputedStyle(e).transform.slice(0, 60)); return chain.join(' | '); });
  await page.mouse.move(fb.x + 100, fb.y + 150, { steps: 5 }); await sleep(700); const t1 = await heroT();
  await page.mouse.move(fb.x + 900, fb.y + 650, { steps: 8 }); await sleep(700); const t2 = await heroT();
  log.push(`hero h1 transform: [${t1}] -> [${t2}] changed=${t1 !== t2}`);
  // grain / glass
  log.push('grain/noise layers: ' + await ev(() => [...document.querySelectorAll('*')].filter(e => { const cs = getComputedStyle(e); const bi = cs.backgroundImage; return (/noise|grain/i.test((e.className.baseVal ?? e.className) + '') || /feTurbulence|noise/i.test(bi)); }).length));
  log.push('backdrop-filter elements: ' + await ev(() => [...document.querySelectorAll('*')].filter(e => { const b = getComputedStyle(e).backdropFilter; return b && b !== 'none'; }).length));
  // hero reserve button
  let b = await f.evaluate(() => scrollY);
  const rb = (await f.evaluateHandle(() => [...document.querySelectorAll('a,button')].find(x => /reserve your table/i.test(x.innerText) && x.getBoundingClientRect().top < innerHeight && x.getBoundingClientRect().width > 0))).asElement();
  if (rb) { const bb = await rb.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(2500); const y = await f.evaluate(() => scrollY); const inView = await ev(() => { const fm = document.querySelector('form'); if (!fm) return 'no form'; const r = fm.getBoundingClientRect(); return `form top=${Math.round(r.top)} bottom=${Math.round(r.bottom)}`; }); log.push(`hero Reserve click: scroll ${b} -> ${y}; ${inView}`); await shot('after_reserve'); }
  // menu: scroll to menu, card tilt
  await f.evaluate(() => { const m = document.querySelector('#menu'); m && m.scrollIntoView(); }); await sleep(1800);
  const card = (await f.evaluateHandle(() => { const cs = [...document.querySelectorAll('#menu article, #menu [class*=card i], #menu li')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 150 && r.height > 200 && r.top > 0 && r.bottom < innerHeight; }); return cs[0] || null; })).asElement();
  if (card) {
    const bb = await card.boundingBox(); const tr = () => card.evaluate(e => { const out = []; let x = e; for (let i = 0; i < 3 && x; i++, x = x.firstElementChild) out.push(getComputedStyle(x).transform.slice(0, 50) + ' sh=' + getComputedStyle(x).boxShadow.slice(0, 40)); return out.join(' | '); });
    const t0 = await tr(); await page.mouse.move(bb.x + bb.width * 0.15, bb.y + bb.height * 0.15, { steps: 6 }); await sleep(600); const ta = await tr(); await page.mouse.move(bb.x + bb.width * 0.85, bb.y + bb.height * 0.85, { steps: 6 }); await sleep(600); const tb = await tr();
    log.push(`card tilt: idle[${t0}]\n   topleft[${ta}]\n   botright[${tb}]`); await shot('card_hover');
    await page.mouse.move(fb.x + 5, fb.y + 5); await sleep(300);
  } else log.push('no menu card found');
  // menu filters
  const filt = await ev(() => [...document.querySelectorAll('#menu button,[role=tab]')].filter(x => x.getBoundingClientRect().width > 0).map(x => x.innerText.trim().replace(/\s+/g, ' ')).filter(t => t && t.length < 30).slice(0, 8));
  log.push('menu buttons: ' + JSON.stringify(filt));
  for (const t of filt.filter(x => /flame|fire|earth|sweet/i.test(x)).slice(0, 3)) { const before = await ev(() => [...document.querySelectorAll('#menu h3')].filter(h => h.getBoundingClientRect().width > 0 && getComputedStyle(h.closest('article,li,div')).opacity !== '0').map(h => h.innerText).join(', ')); await s.click({ text: t, sel: '#menu button, [role=tab]' }, 1200); const after = await ev(() => [...document.querySelectorAll('#menu h3')].filter(h => { const c = h.closest('article,li,[class*=card]') || h; const r = c.getBoundingClientRect(); return r.width > 0 && getComputedStyle(c).display !== 'none' && getComputedStyle(c).opacity !== '0'; }).map(h => h.innerText).join(', ')); log.push(`filter ${t}: ${after}`); }
  // discover dish / card click
  const disc = (await f.evaluateHandle(() => [...document.querySelectorAll('#menu a,#menu button')].find(x => /discover the dish|\+|view|full menu/i.test(x.innerText + (x.getAttribute('aria-label') || '')) && x.getBoundingClientRect().width > 0))).asElement();
  if (disc) { const lab = await disc.evaluate(x => (x.innerText || x.getAttribute('aria-label')).trim().slice(0, 40)); const before = await T(); const bb = await disc.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1300); const dl = await ev(() => [...document.querySelectorAll('[role=dialog],dialog[open]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)).join(' ## ')); log.push(`menu item click [${lab}]: dialog=${dl} +[${(await T()).split('\n').filter(l => l.trim() && !before.includes(l)).slice(0, 5).join(' | ')}]`); await shot('dish'); await page.keyboard.press('Escape'); await sleep(500); }
  // full menu button (A)
  const fm = (await f.evaluateHandle(() => [...document.querySelectorAll('a,button')].find(x => /full menu/i.test(x.innerText) && x.getBoundingClientRect().width > 0))).asElement();
  if (fm) { const before = await T(); const bb = await fm.boundingBox(); if (bb) { await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1300); log.push('full menu click: dialog=' + await ev(() => [...document.querySelectorAll('[role=dialog],dialog[open]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 200)).join(' ## ')) + ' +[' + (await T()).split('\n').filter(l => l.trim() && !before.includes(l)).slice(0, 5).join(' | ') + ']'); await page.keyboard.press('Escape'); await sleep(500); } }
  fs.writeFileSync(path.join(OUT, `${TAG}_rest.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|status of 404|CORS|ERR_FAILED/.test(l)).join('\n'));
  await s.close();
})();

