  log.push('fields: ' + JSON.stringify(fields));
  const fill = async (sel, val) => { const h = await f.$(sel); if (!h) return 'nf ' + sel; await h.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(200); const tag = await h.evaluate(e => e.tagName + ':' + e.type); if (tag.startsWith('SELECT')) { const v = await h.evaluate(e => e.options[Math.min(2, e.options.length - 1)].value); await h.select(v); return 'sel ' + v; } if (/date/.test(tag)) { await h.evaluate(e => { const d = new Date(Date.now() + 5 * 864e5); const v = d.toISOString().slice(0, 10); const st = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; st.call(e, v); e.dispatchEvent(new Event('input', { bubbles: true })); e.dispatchEvent(new Event('change', { bubbles: true })); }); return 'date'; } if (/time/.test(tag)) { await h.evaluate(e => { const st = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set; st.call(e, '19:30'); e.dispatchEvent(new Event('input', { bubbles: true })); e.dispatchEvent(new Event('change', { bubbles: true })); }); return 'time'; } await h.click({ clickCount: 3 }); await page.keyboard.type(val); return 'typed'; };
