  const sels = await f.$$('form select'); for (const se of sels) { const v = await se.evaluate(e => e.options[Math.min(2, e.options.length - 1)].value); await se.select(v); }
  b = await T(); await clickH(sub, 2500);
  log.push('valid submit: +[' + await diff(b) + '] dialog=' + await dlg() + ' toast=' + await toast() + ' invalid=' + await ev(() => [...document.querySelectorAll('form :invalid')].map(e => (e.name || e.id) + ':' + e.validationMessage).join(',')));
  await shot('valid_submit');
