const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path'); const crypto = require('crypto');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3500);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const fb = await (await f.frameElement()).boundingBox();
  const T = () => s.text(); const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 10).join(' | ').slice(0, 450);
  const ev = (fn, ...a) => Promise.race([f.evaluate(fn, ...a), new Promise(r => setTimeout(() => r('TIMEOUT'), 8000))]);
  const dlg = () => ev(() => [...document.querySelectorAll('[role=dialog],dialog[open]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 450)).join(' ## '));
  const toast = () => ev(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 200));
  const hash = async (clip) => crypto.createHash('md5').update(await page.screenshot({ clip })).digest('hex').slice(0, 8);
  const click = async (q, w = 1000) => { const b = await T(); const el = await s.click(q, w); return { el, d: await diff(b) }; };
  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };
  if (TAG === 'A') {
    const fills = () => ev(() => [...document.querySelectorAll('path[aria-label]')].slice(0, 6).map(p => p.getAttribute('aria-label').split('.')[0] + '=' + getComputedStyle(p).fill).join(' ; '));
    await ev(() => document.querySelector('#data')?.scrollIntoView()); await sleep(1200);
    log.push('map all adults: ' + await fills());
    const sel = await f.$('select'); for (const v of ['Women', 'Men']) { const val = await sel.evaluate((e, v) => [...e.options].find(o => o.text === v).value, v); const b = await T(); await sel.select(val); await sleep(1000); log.push(`filter ${v}: ${await fills()} | +[${(await diff(b)).slice(0, 200)}]`); }
    await shot('men');
    let r = await click({ text: 'Mortality', sel: '[role=tab],button' }); log.push('Mortality tab: ' + await fills() + ' | +[' + r.d.slice(0, 250) + ']'); await shot('mortality');
    await click({ text: 'Prevalence', sel: '[role=tab],button' });
    // hover + click a state on the map
    const st = (await f.evaluateHandle(() => [...document.querySelectorAll('path[aria-label^="Texas"]')][0])).asElement(); const bb = await st.boundingBox();
    let b = await T(); await s.hover(bb.x + bb.width / 2, bb.y + bb.height / 2, 800); log.push('hover Texas: +[' + await diff(b) + ']'); await shot('hover_tx');
    b = await T(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1000); log.push('click Texas: +[' + await diff(b) + '] dlg=' + await dlg()); await shot('click_tx'); await esc();
    r = await click({ label: 'Table view' }); log.push('Table view: +[' + r.d.slice(0, 300) + ']'); await shot('table');
    const sortBtn = await s.find({ text: 'Highest first' }); if (sortBtn) { r = await click({ text: 'Highest first' }); log.push('sort click: +[' + r.d.slice(0, 200) + ']'); }
    await click({ label: 'Map view' });
    r = await click({ text: 'Explore all 50 states' }); log.push('Explore all 50 states: +[' + r.d.slice(0, 200) + '] dlg=' + (await dlg()).slice(0, 200));
    await esc();
    // Know your risk wizard
    await ev(() => scrollTo(0, 0)); await sleep(500);
    await s.click({ text: 'Know your risk', sel: 'button' }, 1200);
    log.push('risk step1: ' + (await dlg()).slice(0, 450)); await shot('risk1');
    for (let step = 0; step < 4; step++) {
      // pick first option in each radio group
      await ev(() => { const d = [...document.querySelectorAll('[role=dialog],dialog[open]')].pop(); const groups = {}; for (const i of d.querySelectorAll('input[type=radio]')) { if (!groups[i.name]) { groups[i.name] = 1; } } return Object.keys(groups).length; });
      const radios = await f.$$('[role=dialog] input[type=radio], dialog[open] input[type=radio], [role=dialog] [role=radio], [role=dialog] button[aria-pressed]');
      const seen = new Set(); for (const rd of radios) { const nm = await rd.evaluate(e => e.name || e.closest('[role=radiogroup]')?.getAttribute('aria-label') || e.parentElement.parentElement.textContent.slice(0, 20)); if (seen.has(nm)) continue; seen.add(nm); const bx = await rd.boundingBox(); if (bx) { await rd.evaluate(e => e.scrollIntoView({ block: 'center' })); const bx2 = await rd.boundingBox(); await page.mouse.click(bx2.x + bx2.width / 2, bx2.y + bx2.height / 2); await sleep(200); } }
      const nums = await f.$$('[role=dialog] input[type=number], dialog[open] input[type=number]'); for (const nb of nums) { await nb.click({ clickCount: 3 }); await page.keyboard.type('55'); }
      const nx = (await f.evaluateHandle(() => { const d = [...document.querySelectorAll('[role=dialog],dialog[open]')].pop(); return [...d.querySelectorAll('button')].find(b => /next|continue|see my|results|finish|show/i.test(b.innerText) && !b.disabled) || null; })).asElement();
      if (!nx) { log.push('no next button at step ' + step); break; }
      const lab = await nx.evaluate(e => e.innerText.trim()); const bx = await nx.boundingBox(); await page.mouse.click(bx.x + bx.width / 2, bx.y + bx.height / 2); await sleep(1000);
      log.push(`risk after "${lab}": ` + (await dlg()).slice(0, 400));
    }
    await shot('risk_end'); await esc();
  } else {
    // 3D heart
    const cv = await f.$('canvas'); const cb = await cv.boundingBox(); const clip = { x: cb.x + cb.width * 0.25, y: cb.y + cb.height * 0.2, width: cb.width * 0.5, height: cb.height * 0.6 };
