const puppeteer = require('puppeteer-core');
const http = require('http');
const fs = require('fs');
const path = require('path');

const ROOT = process.argv[2];
const OUT = process.argv[3];
const ONLY = process.argv[4];
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

const server = http.createServer((req, res) => {
  const f = path.join(ROOT, decodeURIComponent(req.url.split('?')[0]));
  if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) { res.writeHead(404); return res.end(); }
  res.writeHead(200, { 'Content-Type': f.endsWith('.html') ? 'text/html' : f.endsWith('css2') ? 'text/css' : 'application/octet-stream' });
  fs.createReadStream(f).pipe(res);
}).listen(8766);

const sleep = ms => new Promise(r => setTimeout(r, ms));

// label match: aria-label or innerText (exact-ish, case-insensitive startsWith)
const STEPS = {
  A: ['Tangerine', 'Lilac', 'Matcha', 'Butter', 'Ink', 'Tangerine', 'Wink', 'Dreamy', 'Gentle', 'Auto-rotate Sol', 'Auto-rotate Sol',
      'Download a transparent PNG snapshot', 'Download model GLB', 'Reset view', 'Expand 3D viewer', 'ESC', 'Playground', 'The collection', 'ESC',
      'Our little story', 'ESC', 'A little joy, by design.', 'ESC', 'Meet the whole family', 'ESC', 'softform'],
  B: ['Peach body color', 'Lilac body color', 'Sage body color', 'Cloud body color', 'Butter body color', 'Dreamy', 'Curious', 'Happy',
      'Glossy', 'Soft matte', 'MOTION', 'MOTION', 'Front', '3D', 'Hide the studio grid', 'Show the studio grid', 'Reset camera view',
      'Save character to collection', 'My collection', 'ESC', 'Expand preview', 'ESC', 'Export character', 'ESC',
      '02 / THE LITTLE FAMILY', '04 / THE LITTLE FAMILY', 'Reset character to the original settings',
      'The playground', 'The collection', 'Our story', 'ESC', 'Your own little universe', 'ESC', 'Made with imagination', 'ESC', 'littleform.'],
};
const FILES = { A: 'saved_resource.html', B: 'saved_resource(1).html' };

async function snapshotState(page) {
  return page.evaluate(() => ({
    url: location.href.split('/').pop(), scrollY: Math.round(scrollY),
    text: document.body.innerText,
    dialogs: [...document.querySelectorAll('[role=dialog],dialog[open],[aria-modal=true],.toast,[role=status],[role=alert]')].map(d => (d.innerText || '').trim().slice(0, 200)),
  }));
}

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME, headless: 'new',
    args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--no-sandbox'],
  });
  for (const k of Object.keys(STEPS)) {
    if (ONLY && ONLY !== k) continue;
    const dl = path.join(OUT, `dl_${k}`); fs.mkdirSync(dl, { recursive: true });
    const page = await browser.newPage();
    await page.setViewport({ width: 1440, height: 900 });
    const cdp = await page.createCDPSession();
    await cdp.send('Browser.setDownloadBehavior', { behavior: 'allow', downloadPath: dl, eventsEnabled: true });
    const logs = [];
    page.on('console', m => { if (m.type() !== 'warn') logs.push(`[${m.type()}] ${m.text()}`); });
    page.on('pageerror', e => logs.push(`[pageerror] ${e.message}`));
    page.on('popup', p => logs.push(`[popup] ${p.url()}`));
    page.on('dialog', async d => { logs.push(`[jsdialog] ${d.message()}`); await d.dismiss(); });
    await page.goto(`http://localhost:8766/${encodeURIComponent(FILES[k])}`, { waitUntil: 'networkidle2', timeout: 60000 });
    await sleep(3000);

    // drag + wheel on canvas
    const box = await (await page.$('canvas')).boundingBox();
    const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
    await page.mouse.move(cx, cy); await page.mouse.down();
    for (let i = 1; i <= 12; i++) { await page.mouse.move(cx + i * 18, cy + i * 4); await sleep(20); }
    await page.mouse.up(); await sleep(700);
    await page.screenshot({ path: path.join(OUT, `${k}_s00_drag.png`) });
    await page.mouse.move(cx, cy);
    for (let i = 0; i < 5; i++) { await page.mouse.wheel({ deltaY: -200 }); await sleep(80); }
    await sleep(700);
    const sy = await page.evaluate(() => scrollY);
    await page.screenshot({ path: path.join(OUT, `${k}_s01_zoom.png`) });
    logs.push(`after wheel-in scrollY=${sy}`);

    let prev = await snapshotState(page);
    const report = [];
    let n = 2;
    for (const label of STEPS[k]) {
      const before = new Set(fs.readdirSync(dl));
      if (label === 'ESC') { await page.keyboard.press('Escape'); await sleep(600); }
      else {
        const handle = await page.evaluateHandle((label) => {
          const norm = s => (s || '').trim().replace(/\s+/g, ' ').toLowerCase();
          const L = label.toLowerCase();
          const els = [...document.querySelectorAll('button, a, [role=switch], input')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; });
          if (L === 'motion') return els.find(e => e.getAttribute('role') === 'switch' || /motion|float/i.test(e.getAttribute('aria-label') || '')) || els.find(e => norm(e.innerText) === '' && e.closest('div') && /motion/i.test(e.closest('div').parentElement.innerText));
          return els.find(e => norm(e.getAttribute('aria-label')) === L) || els.find(e => norm(e.innerText) === L) || els.find(e => norm(e.innerText).startsWith(L)) || els.find(e => norm(e.getAttribute('aria-label')).startsWith(L));
        }, label);
        const el = handle.asElement();
        if (!el) { report.push(`#${n} [${label}] NOT FOUND`); n++; continue; }
        await el.evaluate(e => e.scrollIntoView({ block: 'center' }));
        await sleep(200);
        try { await el.click(); } catch (e) { report.push(`#${n} [${label}] click error ${e.message}`); }
        await sleep(1500);
      }
      const cur = await snapshotState(page);
      const after = fs.readdirSync(dl).filter(f => !before.has(f));
      const addedLines = cur.text.split('\n').filter(l => l.trim() && !prev.text.includes(l)).slice(0, 12);
      const removedLines = prev.text.split('\n').filter(l => l.trim() && !cur.text.includes(l)).slice(0, 6);
      report.push(`#${n} [${label}] url=${cur.url} scrollY=${cur.scrollY} dialogs=${JSON.stringify(cur.dialogs)} downloads=${JSON.stringify(after)}\n    +${JSON.stringify(addedLines)}\n    -${JSON.stringify(removedLines)}`);
      await page.screenshot({ path: path.join(OUT, `${k}_s${String(n).padStart(2, '0')}_${label.replace(/[^a-z0-9]+/gi, '_').slice(0, 30)}.png`) });
      prev = cur; n++;
    }
    await sleep(1500);
    const files = fs.readdirSync(dl).map(f => `${f} ${fs.statSync(path.join(dl, f)).size}B`);
    fs.writeFileSync(path.join(OUT, `${k}_interact.txt`), report.join('\n') + '\n\nDOWNLOADS:\n' + files.join('\n') + '\n\nLOGS:\n' + logs.join('\n'));
    console.log(k, 'done', files);
    await page.close();
  }
  await browser.close(); server.close();
})();

