  }));
  const cardTitle = () => page.evaluate(() => {
    const t = document.body.innerText;
    const h = [...document.querySelectorAll('[role=tooltip],[role=dialog],[class*=card],[class*=popover],[class*=tooltip]')].filter(e => e.getBoundingClientRect().width > 100).map(e => e.innerText.split('\n').slice(0, 3).join(' / '));
    return h.join(' || ').slice(0, 160);
  });
  let ok = 0, bad = [];
  for (const t of targets) {
    for (const kind of ['bubble', 'label']) {
      const p = t[kind]; if (!p) continue;
      await page.mouse.move(5, 5); await sleep(250);
      await page.mouse.move(p.x, p.y, { steps: 3 }); await sleep(600);
      const top = await page.evaluate((x, y) => { const e = document.elementFromPoint(x, y); const g = e && e.closest('g[aria-label]'); return g ? g.getAttribute('aria-label').split(',')[0] : (e ? e.tagName : 'none'); }, p.x, p.y);
      const card = await cardTitle();
      const match = card.includes(t.title.slice(0, 15));
      if (kind === 'bubble') { if (match) ok++; else bad.push(t.title); }
      console.log(`${kind.padEnd(6)} [${t.title.slice(0, 40)}] topEl=[${top.slice(0, 40)}] match=${match} card=${card.slice(0, 110)}`);
    }
  }
  console.log(`\nBUBBLE HOVER OK ${ok}/${targets.length}; failing: ${JSON.stringify(bad)}`);
  await browser.close(); server.close();
})();

const puppeteer = require('puppeteer-core');
const http = require('http'); const fs = require('fs'); const path = require('path');
const ROOT = process.argv[2], OUT = process.argv[3];
