const STEPS = {
  A: ['1M', '6M', '1Y', '3Y', '5Y', 'Earnings', 'Price targets', 'Insider trades', 'Product launches', 'Major news', 'All events', 'BRUSH', 'Reset view',
      'DATEPICK', 'ESC', 'Expand chart', 'ESC', 'STOCK TIMELINE'],
  B: ['1M', '3M', '6M', 'YTD', '1Y', '3Y', 'ALL', '5Y', 'Earnings', 'Analyst targets', 'Insider trades', 'Products', 'Major news', 'All events', 'Show events', 'Show events',
      'BRUSH', 'DBLCLICK', 'Export visible price history as CSV', 'How to use this timeline', 'ESC', 'Data & sources', 'ESC', 'Expand timeline', 'ESC', 'TESLA'],
};
(async () => {
  const browser = await puppeteer.launch({ executablePath: 'C:/Program Files/Google/Chrome/Application/chrome.exe', headless: 'new', args: ['--no-sandbox'] });
  for (const k of ['A', 'B']) {
    const dl = path.join(OUT, 'dl_' + k); fs.mkdirSync(dl, { recursive: true });
    const page = await browser.newPage(); await page.setViewport({ width: 1440, height: 900 });
    const cdp = await page.createCDPSession(); await cdp.send('Browser.setDownloadBehavior', { behavior: 'allow', downloadPath: dl });
    const log = [];
    page.on('console', m => { if (m.type() === 'error') log.push(`   [console.error] ${m.text()}`); });
    page.on('pageerror', e => log.push(`   [pageerror] ${e.message}`));
    page.on('popup', p => log.push(`   [popup] ${p.url()}`));
    await page.goto(`http://localhost:8772/${encodeURIComponent(FILES[k])}`, { waitUntil: 'networkidle2' }); await sleep(1500);
    const state = () => page.evaluate((k) => {
      const svg = [...document.querySelectorAll('svg')].sort((a, b) => b.getBoundingClientRect().width * b.getBoundingClientRect().height - a.getBoundingClientRect().width * a.getBoundingClientRect().height)[0];
      const r = svg.getBoundingClientRect();
      const texts = [...svg.querySelectorAll('text')].filter(t => { const b = t.getBoundingClientRect(); return b.width > 0 && b.top > r.top + r.height * 0.8; }).map(t => t.textContent.trim()).filter(Boolean);
      const sel = k === 'A' ? 'button[aria-label*=", 20"]' : 'g[aria-label*="Press Enter"]';
      const ev = [...document.querySelectorAll(sel)].filter(e => { const b = e.getBoundingClientRect(); return b.width > 0 && getComputedStyle(e).opacity !== '0' && getComputedStyle(e).visibility !== 'hidden'; }).length;
      const dlg = [...document.querySelectorAll('[role=dialog],[aria-modal=true],dialog[open],[role=status],[role=alert],[role=listbox],[role=menu]')].map(d => d.innerText.trim().replace(/\s+/g, ' ').slice(0, 220)).filter(Boolean);
      const head = document.body.innerText.match(/\$[\d,.]+\s*(USD)?\s*\n?[+−-][\d.]+%/)?.[0]?.replace(/\s+/g, ' ');
      return { xTicks: texts.join(','), events: ev, dlg, head, fs: !!document.fullscreenElement, scrollY };
    }, k);
    let n = 0;
    for (const s of STEPS[k]) {
      const before = new Set(fs.readdirSync(dl));
      if (s === 'ESC') { await page.keyboard.press('Escape'); await sleep(500); }
      else if (s === 'BRUSH' || s === 'DBLCLICK') {
        const h = await page.$(k === 'A' ? 'button[aria-label="Start of timeline window"]' : 'button[aria-label="Timeline start date"]');
        const b = await h.boundingBox();
        if (s === 'BRUSH') {
          await page.mouse.move(b.x + b.width / 2, b.y + b.height / 2); await page.mouse.down();
          await page.mouse.move(b.x + 500, b.y + b.height / 2, { steps: 12 }); await page.mouse.up(); await sleep(800);
        } else {
          await page.mouse.click(b.x + 700, b.y + b.height / 2, { clickCount: 2 }); await sleep(800);
        }
      } else if (s === 'DATEPICK') {
        await page.click('button[aria-label^="Custom date range"]').catch(e => log.push('datepick err ' + e.message)); await sleep(800);
      } else {
        const ok = await page.evaluate((s) => {
          const norm = t => (t || '').trim().replace(/\s+/g, ' ');
          const els = [...document.querySelectorAll('button,a,[role=switch]')].filter(e => e.getBoundingClientRect().width > 0);
          const e = els.find(e => norm(e.getAttribute('aria-label')) === s) || els.find(e => norm(e.innerText) === s) || els.find(e => norm(e.innerText).startsWith(s));
          if (!e) return false; e.click(); return true;
        }, s);
        if (!ok) { log.push(`#${n} [${s}] NOT FOUND`); n++; continue; }
        await sleep(900);
      }
      const st = await state();
      const newf = fs.readdirSync(dl).filter(f => !before.has(f));
      log.push(`#${n} [${s}] events=${st.events} head=${st.head} fs=${st.fs} scrollY=${st.scrollY} x=[${st.xTicks}] dlg=${JSON.stringify(st.dlg)} dl=${JSON.stringify(newf)}`);
      await page.screenshot({ path: path.join(OUT, `${k}_${String(n).padStart(2, '0')}_${s.replace(/[^a-z0-9]+/gi, '_').slice(0, 20)}.png`) });
      n++;
    }
    await sleep(800);
    const files = fs.readdirSync(dl);
    for (const f of files) log.push(`FILE ${f} ${fs.statSync(path.join(dl, f)).size}B head: ${fs.readFileSync(path.join(dl, f), 'utf8').split('\n').slice(0, 3).join(' / ')}`);
    fs.writeFileSync(path.join(OUT, `${k}_controls.txt`), log.join('\n'));
    console.log(k, 'done');
    await page.close();
  }
  await browser.close(); server.close();
})();

