    for (let i = 0, y = 0; y < docH && i < 3; i++, y += 760) { await frame.evaluate(y => scrollTo(0, y), y); await sleep(400); await s.shot(path.join(OUT, `${k}_${WIDTH}_screen${i}.png`)); }
    await frame.evaluate(() => scrollTo(0, 0)); await sleep(300);

    // chart hover (bring chart into view first)
    const svgBox = await frame.evaluate(() => { const svg = [...document.querySelectorAll('svg')].sort((a, b) => b.getBoundingClientRect().width * b.getBoundingClientRect().height - a.getBoundingClientRect().width * a.getBoundingClientRect().height)[0]; svg.scrollIntoView({ block: 'center' }); const r = svg.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; });
    await sleep(400);
    for (const fx of [0.1, 0.4, 0.7]) { await s.hover(svgBox.x + svgBox.w * fx, svgBox.y + svgBox.h * 0.85); log.push(`chart hover ${fx}: ${await diff()}`); }
    await s.shot(path.join(OUT, `${k}_${WIDTH}_chart_hover.png`));
    await s.hover(2, 2);

    // every bubble: real hover at its icon; check card visible & inside the frame
    const sel = k === 'A' ? 'button[aria-label*=", 20"]:not([aria-label^="Custom"])' : 'g[aria-label*="Press Enter"]';
    const n = await frame.evaluate(sel => document.querySelectorAll(sel).length, sel);
    let okCount = 0, clipped = [], missing = [];
    for (let i = 0; i < n; i++) {
      const t = await frame.evaluate((sel, i) => {
        const e = document.querySelectorAll(sel)[i]; e.scrollIntoView({ block: 'nearest' });
        let tgt = e; const circles = [...e.querySelectorAll('circle')].sort((a, b) => (+b.getAttribute('r')) - (+a.getAttribute('r'))); if (circles.length) tgt = circles[0];
        const r = tgt.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2, title: e.getAttribute('aria-label').split(',')[0] };
      }, sel, i);
      await s.hover(t.x, t.y, 550);
      const card = await frame.evaluate((title) => {
        // find the smallest visible element whose text includes the event title and has a description-length text
        const cands = [...document.querySelectorAll('div,section,article,aside,[role=tooltip],[role=dialog]')].filter(d => { const r = d.getBoundingClientRect(); const st = getComputedStyle(d); return r.width > 120 && r.height > 60 && st.visibility !== 'hidden' && +st.opacity > 0.05 && d.innerText.includes(title.slice(0, 18)) && d.innerText.length > 80 && d.innerText.length < 900; });
        cands.sort((a, b) => a.innerText.length - b.innerText.length);
        const c = cands[0]; if (!c) return null; const r = c.getBoundingClientRect();
        return { top: Math.round(r.top), bottom: Math.round(r.bottom), left: Math.round(r.left), right: Math.round(r.right), vw: innerWidth, vh: innerHeight };
      }, t.title);
      if (!card) missing.push(t.title);
      else { okCount++; if (card.top < 0 || card.left < 0 || card.bottom > card.vh || card.right > card.vw) clipped.push(`${t.title} [${card.left},${card.top},${card.right},${card.bottom}]`); }
      if (i === 0 || i === n - 1) await s.shot(path.join(OUT, `${k}_${WIDTH}_bubble_${i}.png`));
      await s.hover(2, 2, 150);
    }
    log.push(`BUBBLES: ${okCount}/${n} showed a card; missing=${JSON.stringify(missing)}; clipped=${JSON.stringify(clipped)}`);

    // controls (real clicks)
    await frame.evaluate(() => scrollTo(0, 0));
    let idx = 0;
    for (const c of CONTROLS[k]) {
      if (c === 'ESC') { await page.keyboard.press('Escape'); await sleep(500); log.push(`#${idx++} ESC`); continue; }
      const before = fs.existsSync(dl) ? fs.readdirSync(dl).length : 0;
      const el = await s.click(c);
      const st = await frame.evaluate(() => ({ pct: (document.body.innerText.match(/[+−-][\d.]+%/) || [''])[0], dlg: [...document.querySelectorAll('[role=dialog],[aria-modal=true],dialog[open],[role=status],[role=alert]')].map(d => d.innerText.trim().replace(/\s+/g, ' ').slice(0, 70)).filter(Boolean) }));
      const after = fs.existsSync(dl) ? fs.readdirSync(dl).length : 0;
      log.push(`#${idx++} ${JSON.stringify(c)} found=${!!el} pct=${st.pct} dlg=${JSON.stringify(st.dlg)} newFiles=${after - before}`);
      if (c.label && /Expand|How to|CSV/.test(c.label) || c.text === 'Data & sources' || (c.css || '').includes('Custom')) await s.shot(path.join(OUT, `${k}_${WIDTH}_ctl_${idx}.png`));
    }
    // brush drag with real mouse
    const hs = await s.find({ css: k === 'A' ? 'button[aria-label="Start of timeline window"]' : 'button[aria-label="Timeline start date"]' });
    if (hs) {
      await hs.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(300);
      const bb = await hs.boundingBox();
      await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 2); await page.mouse.down(); await page.mouse.move(bb.x + WIDTH * 0.35, bb.y + bb.height / 2, { steps: 12 }); await page.mouse.up(); await sleep(700);
      log.push(`brush drag → ${await frame.evaluate(() => (document.body.innerText.match(/[+−-][\d.]+%/) || [''])[0])}`);
    }
    await sleep(1500);
    log.push('FILES: ' + JSON.stringify(fs.readdirSync(dl)));
    fs.writeFileSync(path.join(OUT, `${k}_${WIDTH}_frame.txt`), log.join('\n'));
    console.log(`==== ${k} @${WIDTH}x800 (sandboxed frame)\n` + log.join('\n'));
    await s.close();
  }
})();

