const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3000);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const T = () => s.text();
  const toast = () => f.evaluate(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert],[aria-live]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 220));
  const progress = () => f.evaluate(() => (document.body.innerText.match(/\d+ of \d+ pieces( placed)?/) || [''])[0] + ' | ' + (document.body.innerText.match(/\d+ left/) || [''])[0] + ' | time ' + (document.body.innerText.match(/\d\d:\d\d/) || [''])[0]);
  // target center of slot for piece index k (page coords)
  const target = (k) => f.evaluate((TAG, k) => {
    if (TAG === 'A') {
      const svg = [...document.querySelectorAll('.puzzle-board svg')].find(x => x.getAttribute('viewBox')); const vb = svg.viewBox.baseVal; const r = svg.getBoundingClientRect();
      const cols = Math.round(vb.width / 200); const cx = (k % cols) * 200 + 100 + vb.x, cy = Math.floor(k / cols) * 200 + 100 + vb.y;
      return { x: r.x + (cx - vb.x) / vb.width * r.width, y: r.y + (cy - vb.y) / vb.height * r.height };
    } else {
      const el = document.querySelector(`#board-slot-${k}`); const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2, empty: el.classList.contains('is-empty') };
    }
  }, TAG, k);
  const pieceIds = () => f.evaluate((TAG) => [...document.querySelectorAll(TAG === 'A' ? 'button.piece[data-piece]' : 'button[data-piece-id]')].filter(e => e.getBoundingClientRect().width > 0).map(e => +(e.getAttribute(TAG === 'A' ? 'data-piece' : 'data-piece-id'))), TAG);
  const fb = await (await f.frameElement()).boundingBox();
  const drag = async (k, slot) => {
    const sel = TAG === 'A' ? `button.piece[data-piece="${k}"]` : `button[data-piece-id="${k}"]`;
    const h = await f.$(sel); if (!h) return 'no piece';
    await h.evaluate(e => e.scrollIntoView({ block: 'nearest' })); await sleep(150);
    const bb = await h.boundingBox(); const t = await target(slot);
    const sx = bb.x + bb.width / 2, sy = bb.y + bb.height / 2, tx = fb.x + t.x, ty = fb.y + t.y;
    await page.mouse.move(sx, sy); await page.mouse.down(); await sleep(60);
    for (let i = 1; i <= 14; i++) { await page.mouse.move(sx + (tx - sx) * i / 14, sy + (ty - sy) * i / 14); await sleep(20); }
    await sleep(80); await page.mouse.up(); await sleep(500);
    return 'ok';
  };
  log.push('start: ' + await progress());
  let ids = await pieceIds(); log.push('tray pieces: ' + JSON.stringify(ids));
  // wrong drop
  const k0 = ids[0]; const wrong = TAG === 'A' ? ((k0 + 1) % 12) : ((k0 + 1) % 16);
  log.push(`wrong drop piece ${k0} -> slot ${wrong}: ${await drag(k0, wrong)} | ${await progress()} | toast=${await toast()}`);
  await shot('wrong_drop');
  log.push('tray after wrong: ' + JSON.stringify(await pieceIds()));
  // correct drop
  log.push(`correct drop piece ${k0}: ${await drag(k0, k0)} | ${await progress()} | toast=${await toast()}`);
  await shot('correct_drop');
  // finish
  for (let guard = 0; guard < 40; guard++) { ids = await pieceIds(); if (!ids.length) break; await drag(ids[0], ids[0]); }
  await sleep(1500);
  log.push('after all drops: ' + await progress() + ' toast=' + await toast());
  log.push('completion: ' + (await T()).split('\n').filter(l => l.trim()).filter(l => /done|complete|solved|well|congrat|finish|you did|beautiful|nice|lovely|minutes|seconds|moves|time/i.test(l)).slice(0, 10).join(' | '));
  log.push('dialog: ' + JSON.stringify(await f.evaluate(() => [...document.querySelectorAll('[role=dialog]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 400)))));
  await shot('complete');
  fs.writeFileSync(path.join(OUT, `${TAG}_pz.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

