// Start a T20 batting match and watch the delivery cycle (no input), dumping candidate moving elements.
const { open, sleep } = require('./frame'); const path = require('path'); const fs = require('fs');
const [ROOT, FILE, OUT, TAG] = process.argv.slice(2);
(async () => {
  const s = await open(ROOT, FILE, { width: 1440, height: 900, sandbox: false }); await sleep(2000);
  const { frame: f, page, log } = s;
  await s.click({ text: 'LET’S PLAY' }, 1500);
  // candidate elements: ball, marker, needle, etc
  const cands = await f.evaluate(() => [...document.querySelectorAll('*')].filter(e => /ball|marker|needle|indicator|cursor|pointer|sweet|zone|meter|timing|bat|bowler|batter|striker/i.test((e.className && e.className.baseVal !== undefined ? e.className.baseVal : e.className) + ' ' + (e.id || ''))).slice(0, 60).map(e => `${e.tagName.toLowerCase()}.${(e.className.baseVal !== undefined ? e.className.baseVal : e.className).toString().slice(0, 60)}${e.id ? '#' + e.id : ''}`));
  log.push('CANDIDATES:\n  ' + [...new Set(cands)].join('\n  '));
  const t0 = Date.now();
  for (let i = 0; i < 40; i++) {
    const st = await f.evaluate(() => {
      const q = sel => document.querySelector(sel);
      const txt = document.body.innerText;
      const score = (txt.match(/\n(\d+)\s*\/\s*(\d+)\b/) || [''])[0].replace(/\s+/g, '');
      const overs = (txt.match(/(\d+\.\d)\s*\/\s*(20|50)/) || [''])[0];
      // any element whose class contains 'ball' : report its position
      const balls = [...document.querySelectorAll('[class*=ball i]')].filter(e => { const r = e.getBoundingClientRect(); return r.width > 0 && r.width < 40; }).map(e => { const r = e.getBoundingClientRect(); return `${Math.round(r.x)},${Math.round(r.y)}`; }).slice(0, 2);
      const markers = [...document.querySelectorAll('[class*=marker i],[class*=needle i],[class*=cursor i],[class*=indicator i]')].filter(e => e.getBoundingClientRect().width > 0).map(e => { const r = e.getBoundingClientRect(); return `${e.className.toString().slice(0, 25)}@${Math.round(r.x)}`; }).slice(0, 3);
      const msgs = [...document.querySelectorAll('[aria-live],[role=status]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean).join(' | ').slice(0, 120);
      return { score, overs, balls, markers, msgs };
    });
    log.push(`${((Date.now() - t0) / 1000).toFixed(1)}s ${JSON.stringify(st)}`);
    if (i % 8 === 0) await s.shot(path.join(OUT, `${TAG}_explore_${i}.png`));
    await sleep(250);
  }
  fs.writeFileSync(path.join(OUT, `${TAG}_explore.txt`), log.join('\n'));
  console.log(log.filter(l => !/allow-scripts|404/.test(l)).join('\n'));
  await s.close();
})();

const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3500);
  const { frame: f, page, log } = s;
  let n = 0; const shot = name => s.shot(path.join(OUT, `${TAG}_${String(++n).padStart(2, '0')}_${name}.png`));
  const ev = (fn, ...a) => Promise.race([f.evaluate(fn, ...a), new Promise(r => setTimeout(() => r('TIMEOUT'), 8000))]);
  const T = async () => { const t = await ev(() => document.body.innerText); return t === 'TIMEOUT' ? '' : t; };
  const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 10).join(' | ').slice(0, 400);
  const dlg = () => ev(() => [...document.querySelectorAll('[role=dialog],dialog[open],[aria-modal=true]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 350)).join(' ## '));
  const toast = () => ev(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 200));
  const clickH = async (h, w = 1000) => { await h.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(500); const bb = await h.boundingBox(); if (!bb) return false; await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(w); return true; };
  const find = (re, scope = 'body') => f.evaluateHandle((re, scope) => [...document.querySelector(scope).querySelectorAll('a,button,[role=tab],[role=button]')].find(x => x.getBoundingClientRect().width > 0 && new RegExp(re, 'i').test(((x.getAttribute('aria-label') || '') + ' ' + x.innerText).trim())) || null, re, scope).then(h => h.asElement());
  const products = () => ev(() => { const cards = [...document.querySelectorAll('button')].filter(b => /add to cart/i.test(b.innerText) && b.getBoundingClientRect().width > 0); return cards.length + ' cards: ' + cards.slice(0, 6).map(b => { let c = b; for (let i = 0; i < 6 && c; i++) { c = c.parentElement; if (c.querySelector('h3,h4')) break; } const h = c && c.querySelector('h3,h4'); return h ? h.innerText.trim() : '?'; }).join(', '); });
  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };

  // category card sizes
  log.push('category cards: ' + JSON.stringify(await ev(() => { const out = []; for (const h of document.querySelectorAll('h2,h3')) { const t = h.innerText.trim().replace(/\s+/g, ' '); if (/^(AUTOMOTIVE|DECALS|WINDSHIELD BANNERS|CAR STICKERS|APPAREL|ACCESSORIES|LIFESTYLE)$/i.test(t)) { let c = h; for (let i = 0; i < 6; i++) { c = c.parentElement; const r = c.getBoundingClientRect(); if (r.width > 150 && r.height > 120) break; } const r = c.getBoundingClientRect(); out.push(`${t}:${Math.round(r.width)}x${Math.round(r.height)}`); } } return out; })));
  // sticky filter: scroll deep and see if a filter bar with category tabs is at top
  for (const y of [1200, 2200, 3000]) { await ev(y => scrollTo(0, y), y); await sleep(900); log.push(`at y=${y} filter bar in view: ` + await ev(() => { const bars = [...document.querySelectorAll('nav,div,section,aside')].filter(e => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return (cs.position === 'sticky' || cs.position === 'fixed') && r.top >= 0 && r.top < 200 && r.height < 160 && r.width > 300; }); return bars.map(e => e.innerText.replace(/\s+/g, ' ').slice(0, 90)).join(' ## ') || 'none'; })); }
  await ev(() => scrollTo(0, 0)); await sleep(500);
  // nav dropdowns
  const nav = await find('^\\s*automotive\\s*$', 'header'); if (nav) { await nav.hover(); await sleep(800); const b = await T(); await clickH(nav, 900); log.push('header Automotive: +[' + await diff(b) + '] dlg=' + (await dlg()).slice(0, 200)); await shot('nav_auto'); await esc(); }
