  const ev = (fn, ...a) => Promise.race([f.evaluate(fn, ...a), new Promise(r => setTimeout(() => r('TIMEOUT'), 8000))]);
  const T = async () => { const t = await ev(() => document.body.innerText); return t === 'TIMEOUT' ? '' : t; };
  const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 10).join(' | ').slice(0, 400);
  const dlg = () => ev(() => [...document.querySelectorAll('[role=dialog],dialog[open],[aria-modal=true]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 350)).join(' ## '));
  const toast = () => ev(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 200));
  const clickH = async (h, w = 1000) => { await h.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(500); const bb = await h.boundingBox(); if (!bb) return false; await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(w); return true; };
  const find = (re, scope = 'body') => f.evaluateHandle((re, scope) => [...document.querySelector(scope).querySelectorAll('a,button,[role=tab],[role=button]')].find(x => x.getBoundingClientRect().width > 0 && new RegExp(re, 'i').test(((x.getAttribute('aria-label') || '') + ' ' + x.innerText).trim())) || null, re, scope).then(h => h.asElement());
