  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };

  // category card sizes
  log.push('category cards: ' + JSON.stringify(await ev(() => { const out = []; for (const h of document.querySelectorAll('h2,h3')) { const t = h.innerText.trim().replace(/\s+/g, ' '); if (/^(AUTOMOTIVE|DECALS|WINDSHIELD BANNERS|CAR STICKERS|APPAREL|ACCESSORIES|LIFESTYLE)$/i.test(t)) { let c = h; for (let i = 0; i < 6; i++) { c = c.parentElement; const r = c.getBoundingClientRect(); if (r.width > 150 && r.height > 120) break; } const r = c.getBoundingClientRect(); out.push(`${t}:${Math.round(r.width)}x${Math.round(r.height)}`); } } return out; })));
  // sticky filter: scroll deep and see if a filter bar with category tabs is at top
  for (const y of [1200, 2200, 3000]) { await ev(y => scrollTo(0, y), y); await sleep(900); log.push(`at y=${y} filter bar in view: ` + await ev(() => { const bars = [...document.querySelectorAll('nav,div,section,aside')].filter(e => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return (cs.position === 'sticky' || cs.position === 'fixed') && r.top >= 0 && r.top < 200 && r.height < 160 && r.width > 300; }); return bars.map(e => e.innerText.replace(/\s+/g, ' ').slice(0, 90)).join(' ## ') || 'none'; })); }
