  let b = await T(); await clickH(atc, 1300); log.push('Add to cart: +[' + await diff(b) + '] toast=' + await toast() + ' dlg=' + (await dlg()).slice(0, 300)); await shot('added'); await esc();
  log.push('cart count: ' + await ev(() => [...document.querySelectorAll('header button, header a')].filter(e => /cart/i.test((e.getAttribute('aria-label') || '') + e.innerText)).map(e => (e.getAttribute('aria-label') || e.innerText).replace(/\s+/g, ' ')).join(' | ')));
  // quick view
  const qv = await find('quick view'); if (qv) { b = await T(); await clickH(qv, 1200); log.push('Quick view: dlg=' + (await dlg()).slice(0, 350)); await shot('quickview'); await esc(); }
  // sort
  const sel = await f.$('select'); if (sel) { const opts = await sel.evaluate(e => [...e.options].map(o => o.text)); const pr = async () => ev(() => [...document.querySelectorAll('*')].filter(e => e.children.length === 0 && /^\$\d/.test(e.innerText || '') && e.getBoundingClientRect().width > 0).slice(0, 6).map(e => e.innerText).join(',')); const p0 = await pr(); const v = await sel.evaluate(e => [...e.options].find(o => /low to high/i.test(o.text)).value); await sel.select(v); await sleep(1200); log.push(`sort ${JSON.stringify(opts)}: prices ${p0} -> ${await pr()}`); }
  // load more
  const more = await find('VIEW ALL GEAR|MORE FOR YOUR BUILD|load more|show more'); if (more) { const p0 = await products(); await clickH(more, 1500); log.push(`load more: ${p0} -> ${await products()}`); }
