  // category card sizes: find elements whose own big heading text equals category
  log.push(`[${width}] category cards: ` + JSON.stringify(await ev(() => { const names = ['AUTOMOTIVE', 'DECALS', 'WINDSHIELD BANNERS', 'WINDSHIELDBANNERS', 'CAR STICKERS', 'APPAREL', 'ACCESSORIES', 'LIFESTYLE']; const out = []; const seen = new Set(); for (const e of document.querySelectorAll('h1,h2,h3,h4,strong,span,p,div')) { if (e.children.length > 2) continue; const t = (e.innerText || '').trim().replace(/\s+/g, ' ').toUpperCase(); if (!names.includes(t.replace(/\s/g, t.includes(' ') ? ' ' : ''))) continue; if (getComputedStyle(e).fontSize.replace('px', '') < 18) continue; let c = e; for (let i = 0; i < 8; i++) { c = c.parentElement; const r = c.getBoundingClientRect(); if (r.width > 180 && r.height > 140) break; } const r = c.getBoundingClientRect(); const key = t + Math.round(r.y); if (seen.has(key)) continue; seen.add(key); out.push(`${t}:${Math.round(r.width)}x${Math.round(r.height)}@y${Math.round(r.y + scrollY)}`); } return out; })));
  if (TAG === 'B') {
    // header dropdown hover
    for (const name of ['AUTOMOTIVE', 'APPAREL']) { const h = (await f.evaluateHandle((n) => [...document.querySelectorAll('header button, header a')].find(x => x.innerText.trim().toUpperCase() === n && x.getBoundingClientRect().width > 0), name)).asElement(); if (!h) { log.push('no header ' + name); continue; } await ev(() => scrollTo(0, 0)); const bb = await h.boundingBox(); const b = await T(); await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 2, { steps: 4 }); await sleep(900); log.push(`hover header ${name}: +[${await diff(b)}]`); await s.shot(path.join(OUT, `B2_nav_${name}.png`)); const b2 = await T(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(900); log.push(`click header ${name}: +[${await diff(b2)}] expanded=${await h.evaluate(e => e.getAttribute('aria-expanded'))}`); const sub = (await f.evaluateHandle(() => [...document.querySelectorAll('a,button')].find(x => /^hoodies$/i.test(x.innerText.trim()) && x.getBoundingClientRect().width > 0))).asElement(); if (sub && name === 'APPAREL') { const b3 = await T(); const sb = await sub.boundingBox(); await page.mouse.click(sb.x + sb.width / 2, sb.y + sb.height / 2); await sleep(1300); log.push('dropdown Hoodies click: +[' + (await diff(b3)).slice(0, 250) + ']'); } await page.mouse.move(5, 790); await sleep(400); }
