    log.push('top buttons: ' + JSON.stringify(arrows));
    const nx = (await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => /next|slide 2|collection/i.test(b.getAttribute('aria-label') || '') && b.getBoundingClientRect().top < 700))).asElement();
    if (nx) { const b = await T(); const bb = await nx.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(1500); log.push('hero next: +[' + await diff(b) + ']'); await s.shot(path.join(OUT, 'B2_hero_next.png')); }
  }
  // neutral hover test on first product card
  const atc = (await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => /add to cart/i.test(b.innerText) && b.getBoundingClientRect().width > 0))).asElement();
  await atc.evaluate(e => e.scrollIntoView({ block: 'center' })); await page.mouse.move(5, 795); await sleep(1200);
  const card = await atc.evaluateHandle(b => { let c = b; for (let i = 0; i < 7; i++) { c = c.parentElement; if (c.getBoundingClientRect().height > 280) return c; } return c; });
  const st = () => card.evaluate(c => { const cs = getComputedStyle(c); const img = c.querySelector('img,svg,[class*=art i],[class*=image i]'); return `tf=${cs.transform.slice(0, 36)} sh=${cs.boxShadow.slice(0, 60)} bc=${cs.borderColor} img=${img ? getComputedStyle(img).transform.slice(0, 36) : ''}`; });
  const s0 = await st(); const bb = await card.asElement().boundingBox(); await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 3, { steps: 5 }); await sleep(800); const s1 = await st();
  log.push(`card hover neutral: [${s0}]\n     -> [${s1}]`); await s.shot(path.join(OUT, `${TAG}2_card_hover.png`));
  fs.writeFileSync(path.join(OUT, `${TAG}_shop2_${width}.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|status of 404|CORS|ERR_FAILED/.test(l)).join('\n'));
  await s.close();
})();

