const { open, sleep } = require('C:/Users/Administrator/AppData/Local/Temp/claude/e--Projects--Linkedin-UI-Berry/13445d85-09b7-4689-af32-d2b4eead7792/scratchpad/tool/frame.js');
const fs = require('fs'); const path = require('path');
const [ROOT, FILE, TAG, OUT] = process.argv.slice(2);
(async () => {
  const s = await open(ROOT, FILE, { width: 1000, height: 800, sandbox: true }); await sleep(3500);
  const { frame: f, page, log } = s;
  const ev = (fn, ...a) => Promise.race([f.evaluate(fn, ...a), new Promise(r => setTimeout(() => r('TIMEOUT'), 8000))]);
  const T = async () => { const t = await ev(() => document.body.innerText); return t === 'TIMEOUT' ? '' : t; };
  const diff = async b => (await T()).split('\n').filter(l => l.trim() && !b.includes(l)).slice(0, 12).join(' | ').slice(0, 450);
  const dlg = () => ev(() => [...document.querySelectorAll('[role=dialog],dialog[open],[aria-modal=true]')].filter(d => d.getBoundingClientRect().width > 0).map(d => d.innerText.replace(/\s+/g, ' ').slice(0, 300)).join(' ## '));
  const toast = () => ev(() => [...new Set([...document.querySelectorAll('[role=status],[role=alert]')].map(e => e.innerText.trim().replace(/\s+/g, ' ')).filter(Boolean))].join(' || ').slice(0, 200));
  const byText = (re, root) => f.evaluateHandle((re, root) => [...document.querySelectorAll((root || '') + ' a,' + (root || '') + ' button')].find(x => x.getBoundingClientRect().width > 0 && new RegExp(re, 'i').test(((x.getAttribute('aria-label') || '') + ' ' + x.innerText).trim())) || null, re, root).then(h => h.asElement());
  const clickH = async (h, w = 1100) => { await h.evaluate(e => e.scrollIntoView({ block: 'center' })); await sleep(400); const bb = await h.boundingBox(); await page.mouse.click(bb.x + bb.width / 2, bb.y + bb.height / 2); await sleep(w); };
  const esc = async () => { await page.keyboard.press('Escape'); await sleep(500); };
  const prods = () => ev(() => (document.body.innerText.match(/(SHOWING \d+ OF \d+[^\n]*|\d+ PRODUCTS)/g) || []).join(' / '));
  // image zoom on hover: compare all descendant transforms
  const atc = (await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => /add to cart/i.test(b.innerText) && b.getBoundingClientRect().width > 0))).asElement();
  await atc.evaluate(e => e.scrollIntoView({ block: 'center' })); await page.mouse.move(5, 795); await sleep(1000);
  const card = await atc.evaluateHandle(b => { let c = b; for (let i = 0; i < 7; i++) { c = c.parentElement; if (c.getBoundingClientRect().height > 280) return c; } return c; });
  const tfs = () => card.evaluate(c => [...c.querySelectorAll('*')].map(e => getComputedStyle(e).transform + '|' + getComputedStyle(e).filter).join(';'));
  const t0 = await tfs(); const bb = await card.asElement().boundingBox(); await page.mouse.move(bb.x + bb.width / 2, bb.y + bb.height / 4, { steps: 5 }); await sleep(900); const t1 = await tfs();
  const a0 = t0.split(';'), a1 = t1.split(';'); const ch = a1.map((v, i) => v !== a0[i] ? i + ':' + a0[i].slice(0, 30) + '=>' + v.slice(0, 40) : null).filter(Boolean);
  log.push('hover inner changes: ' + JSON.stringify(ch.slice(0, 4)));
  await page.mouse.move(5, 795); await sleep(300);
  // search
  await ev(() => scrollTo(0, 0)); await sleep(400);
  const sr = await byText('^\\s*search', 'header'); if (sr) { await clickH(sr, 900); const inp = await f.$('input[type=search], input[placeholder*="earch" i]'); if (inp) { await inp.click(); await page.keyboard.type('hoodie'); await sleep(1200); log.push('search hoodie: ' + (await ev(() => (document.querySelector('[role=dialog],[role=listbox],[class*=search i]')?.innerText || '').replace(/\s+/g, ' ').slice(0, 250)))); await s.shot(path.join(OUT, TAG + '3_search.png')); } else log.push('search: no input; +[' + (await dlg()).slice(0, 150) + ']'); await esc(); }
  // account (B)
  const acc = await byText('your account', 'header'); if (acc) { const b = await T(); await clickH(acc, 900); log.push('account: +[' + await diff(b) + '] dlg=' + (await dlg()).slice(0, 200) + ' toast=' + await toast()); await esc(); }
  // dropdown subcategory click (B) via hover
  if (TAG === 'B') { await ev(() => scrollTo(0, 0)); const h = (await f.evaluateHandle(() => [...document.querySelectorAll('header button, header a')].find(x => x.innerText.trim().toUpperCase() === 'APPAREL'))).asElement(); const hb = await h.boundingBox(); await page.mouse.move(hb.x + hb.width / 2, hb.y + hb.height / 2, { steps: 3 }); await sleep(800); const sub = (await f.evaluateHandle(() => [...document.querySelectorAll('header a, header button, nav a, nav button')].find(x => /^Bonnies$/i.test(x.innerText.trim()) && x.getBoundingClientRect().width > 0))).asElement(); if (sub) { const sb = await sub.boundingBox(); await page.mouse.move(hb.x + hb.width / 2, sb.y + sb.height / 2, { steps: 4 }); await page.mouse.move(sb.x + sb.width / 2, sb.y + sb.height / 2, { steps: 4 }); await sleep(200); const b = await T(); await page.mouse.click(sb.x + sb.width / 2, sb.y + sb.height / 2); await sleep(1500); log.push('dropdown Bonnies: +[' + (await diff(b)).slice(0, 300) + '] ' + await prods()); await s.shot(path.join(OUT, 'B3_bonnies.png')); } else log.push('no Bonnies link in dropdown'); }
  // add to cart + checkout path
  await ev(() => scrollTo(0, 0));
  const atc2 = (await f.evaluateHandle(() => [...document.querySelectorAll('button')].find(b => /add to cart/i.test(b.innerText) && b.getBoundingClientRect().width > 0))).asElement(); await clickH(atc2, 1200); await esc();
  const cart = (await f.evaluateHandle(() => [...document.querySelectorAll('header button, header a')].find(e => /cart/i.test(e.getAttribute('aria-label') || '') && e.getBoundingClientRect().width > 0))).asElement(); await clickH(cart, 1200);
  const btns = await ev(() => { const d = [...document.querySelectorAll('[role=dialog],[aria-modal=true],aside')].filter(x => x.getBoundingClientRect().width > 0).pop(); return d ? [...d.querySelectorAll('button,a')].map(b => (b.getAttribute('aria-label') || b.innerText).trim().replace(/\s+/g, ' ').slice(0, 30)) : []; });
  log.push('cart drawer buttons: ' + JSON.stringify(btns));
  const qty = (await f.evaluateHandle(() => [...document.querySelectorAll('[role=dialog] button, aside button')].find(b => /increase|\+|add one/i.test((b.getAttribute('aria-label') || '') + b.innerText) && b.getBoundingClientRect().width > 0))).asElement();
  if (qty) { const b = await T(); await clickH(qty, 800); log.push('qty +: +[' + await diff(b) + ']'); }
  const co = (await f.evaluateHandle(() => [...document.querySelectorAll('[role=dialog] button, [role=dialog] a, aside button, aside a')].find(b => /checkout|make it yours/i.test((b.getAttribute('aria-label') || '') + b.innerText) && b.getBoundingClientRect().width > 0))).asElement();
  if (co) { const lab = await co.evaluate(e => e.innerText.trim()); const b = await T(); await clickH(co, 1300); log.push(`checkout "${lab}": +[${await diff(b)}] dlg=${(await dlg()).slice(0, 300)} toast=${await toast()}`); await s.shot(path.join(OUT, TAG + '3_checkout.png')); }
  fs.writeFileSync(path.join(OUT, `${TAG}_shop3.txt`), log.join('\n'));
  console.log(`==== ${TAG}\n` + log.filter(l => !/allow-scripts|status of 404|CORS|ERR_FAILED/.test(l)).join('\n'));
  await s.close();
})();

